export const bibliografia = ["Garcia-Tsao G, Abraldes JG, Rich NE, Wong VW. Noninvasive liver disease assessment and the prevention and management of complications of cirrhosis: 2024 AASLD Practice Guidance. Hepatology. 2024.","Kwo PY, Cohen SM, Lim JK. ACG Clinical Guideline: evaluation of abnormal liver chemistries. Am J Gastroenterol. 2017;112(1):18-35.","Reiberger T. The value of liver and spleen stiffness for evaluation of portal hypertension in compensated cirrhosis. Hepatol Commun. 2022;6(5):950-964.","de Franchis R, Bosch J, Garcia-Tsao G, Reiberger T, Ripoll C; Baveno VII Faculty. Baveno VII – Renewing consensus in portal hypertension. J Hepatol. 2022;76(4):959-974.","European Association for the Study of the Liver. EASL Clinical Practice Guidelines for the management of patients with decompensated cirrhosis. J Hepatol. 2018;69(2):406-460.","Biggins SW, Angeli P, Garcia-Tsao G, et al. Diagnosis, evaluation, and management of ascites, spontaneous bacterial peritonitis and hepatorenal syndrome: 2021 practice guidance by the AASLD. Hepatology. 2021;74(2):1014-1048.","Angeli P, Garcia-Tsao G, Nadim MK, Parikh CR. News in pathophysiology, definition and classification of hepatorenal syndrome: a step beyond the ICA consensus document. J Hepatol. 2019;71(4):811-822.","European Association for the Study of the Liver. EASL Clinical Practice Guidelines on the management of hepatic encephalopathy. J Hepatol. 2022;77(3):807-824.","Bajaj JS, Lauridsen M, Tapper EB, et al. Important unresolved questions in the management of hepatic encephalopathy: an ISHEN consensus. Am J Gastroenterol. 2020;115(7):989-1002.","Fallon MB, Krowka MJ. Pulmonary complications of chronic liver disease: hepatopulmonary syndrome and portopulmonary hypertension. Hepatology. 2016;64(2):673-685.","Krowka MJ, Fallon MB, Kawut SM, et al. International Liver Transplant Society practice guidelines: diagnosis and management of hepatopulmonary syndrome and portopulmonary hypertension. Transplantation. 2016;100(7):1440-1452.","European Association for the Study of the Liver. EASL Clinical Practice Guidelines: vascular diseases of the liver. J Hepatol. 2016;64(1):179-202.","O'Leary JG, Greenberg CS, Patton HM, Caldwell SH. AGA Clinical Practice Update: coagulation in cirrhosis. Gastroenterology. 2019;157(1):34-43.","Tandon P, Montano-Loza AJ, Lai JC, Dasarathy S, Merli M. Sarcopenia and frailty in decompensated cirrhosis. J Hepatol. 2021;75(Suppl 1):S147-S162.","Guichelaar MM, Malinchoc M, Sibonga J, et al. Bone metabolism in advanced cholestatic liver disease. Hepatology. 2002;36(4):895-903.","Reiberger T, Puspok A, Schoder M, et al. Austrian consensus guidelines on the management and treatment of portal hypertension. Wien Klin Wochenschr. 2017;129(Suppl 3):135-158.","Heimbach JK, Kulik LM, Finn RS, et al. AASLD guidelines for the treatment of hepatocellular carcinoma. Hepatology. 2018;67(1):358-380.","Singal AG, Llovet JM, Yarchoan M, et al. AASLD Practice Guidance on prevention, diagnosis, and treatment of hepatocellular carcinoma. Hepatology. 2023;78(6):1922-1965.","Reig M, Forner A, Rimola J, et al. BCLC strategy for prognosis prediction and treatment recommendation: the 2022 update. J Hepatol. 2022;76(3):681-693.","Moreau R, Jalan R, Gines P, et al. Acute-on-chronic liver failure is a distinct syndrome that develops in patients with acute decompensation of cirrhosis. Gastroenterology. 2013;144(7):1426-1437.","Vergis N, Warrillow S, Nanchal R. Diagnosis and management of acute-on-chronic liver failure. Clin Liver Dis. 2023;27(3):595-611.","European Association for the Study of the Liver. EASL Clinical Practice Guidelines on acute-on-chronic liver failure. J Hepatol. 2023. doi:10.1016/j.jhep.2023.04.021."];
export const content = {"definicion":{"histologica":"Sustitución difusa del parénquima hepático normal por nódulos de regeneración rodeados de bandas de fibrosis (septos fibrosos), con pérdida de la arquitectura lobulillar normal. Es el estadio final común (F4 de METAVIR) de cualquier hepatopatía crónica progresiva.","clinica":"Síndrome caracterizado por la coexistencia, en grado variable, de insuficiencia hepatocelular (síntesis, detoxificación) e hipertensión portal, que determina el espectro de manifestaciones desde la cirrosis compensada asintomática hasta la descompensada con ascitis, hemorragia variceal, encefalopatía o ictericia.","fisiopatologica":"Proceso dinámico y potencialmente reversible en etapas tempranas, resultante de la activación mantenida de las células estrelladas hepáticas (CEH) en respuesta a daño hepatocelular crónico, con depósito excesivo de matriz extracelular, capilarización sinusoidal y remodelación vascular que perpetúan la lesión incluso al cesar el agente causal.","elementos":[{"nombre":"Fibrosis hepática","detalle":"Depósito neto de colágeno tipo I y III y otras proteínas de matriz extracelular en el espacio de Disse, producido por las CEH activadas (transdiferenciadas a miofibroblastos). Se organiza en septos que conectan espacios porta entre sí y con venas centrales (fibrosis en puente)."},{"nombre":"Nódulos regenerativos","detalle":"Focos de hepatocitos en regeneración rodeados completamente por septos fibrosos, con pérdida de la relación radial normal hepatocito-sinusoide-vena central. Pueden ser micronodulares (<3 mm, típico de alcohol) o macronodulares (>3 mm, típico de hepatitis virales)."},{"nombre":"Distorsión de la arquitectura","detalle":"Pérdida de la unidad lobulillar clásica; los septos fibrosos y nódulos alteran el flujo sanguíneo intrahepático normal, generando cortocircuitos (shunts) intrahepáticos entre la circulación portal y las venas hepáticas que evitan el parénquima funcional."},{"nombre":"Hipertensión portal","detalle":"Elevación del gradiente de presión venosa hepática (HVPG) >5 mmHg, resultado de un componente fijo (aumento de resistencia intrahepática por fibrosis y nódulos) y un componente dinámico (aumento del tono vascular intrahepático por disfunción endotelial con déficit relativo de óxido nítrico intrahepático)."},{"nombre":"Insuficiencia hepatocelular","detalle":"Reducción de la masa funcional de hepatocitos que compromete la síntesis de proteínas (albúmina, factores de coagulación), la detoxificación (amonio, bilirrubina) y el metabolismo, manifestándose como hipoalbuminemia, coagulopatía, ictericia y encefalopatía."}]},"epidemiologia":{"datos":"La cirrosis es la 11ª causa de muerte a nivel mundial y la enfermedad hepática crónica en su conjunto (cirrosis + HCC) representa más de 2 millones de muertes anuales. La prevalencia global estimada es de 0.1-0.2%, con tendencia creciente atribuible a MASLD/MASH por la epidemia de obesidad y diabetes. Aproximadamente el 40-50% de los pacientes están compensados y asintomáticos al momento del diagnóstico.","causas":[{"nombre":"MASLD/MASH (antes NAFLD/NASH)","detalle":"Primera causa de enfermedad hepática crónica a nivel mundial; se asocia a síndrome metabólico, obesidad, diabetes tipo 2 y dislipidemia. Nueva nomenclatura 2023 (Rome consensus): esteatosis hepática asociada a disfunción metabólica (MASLD) y su forma inflamatoria MASH."},{"nombre":"Alcohol (ALD)","detalle":"Consumo de riesgo >21 unidades/semana en hombres y >14 en mujeres de forma sostenida; el espectro va de esteatosis simple a hepatitis alcohólica y cirrosis. Frecuente cofactor con MASLD (MetALD) y con hepatitis virales."},{"nombre":"Hepatitis viral crónica B","detalle":"Persistencia de HBsAg >6 meses; el riesgo de cirrosis se relaciona con carga viral sostenida, coinfección con VHD/VIH y genotipo. Vacunación ha reducido su incidencia en cohortes jóvenes."},{"nombre":"Hepatitis viral crónica C","detalle":"Principal causa histórica de cirrosis en muchos países; la disponibilidad de antivirales de acción directa (AAD) con tasas de curación >95% ha reducido su progresión, aunque la fibrosis avanzada preexistente puede persistir tras la cura virológica."},{"nombre":"Hepatitis autoinmune (HAI)","detalle":"Predominio en mujeres; asociada a hipergammaglobulinemia, ANA/ASMA/anti-LKM1 positivos e infiltrado de interfase en biopsia. Hasta 30% se presenta ya con cirrosis al diagnóstico."},{"nombre":"Colangitis biliar primaria (CBP)","detalle":"Enfermedad colestásica autoinmune de conductillos biliares interlobulillares, predominio en mujeres de edad media, AMA positivo en >90%, asociada a prurito y fatiga."},{"nombre":"Colangitis esclerosante primaria (CEP)","detalle":"Fibrosis y estenosis de vía biliar intra y extrahepática, fuerte asociación con enfermedad inflamatoria intestinal (colitis ulcerosa), riesgo elevado de colangiocarcinoma."},{"nombre":"Hemocromatosis hereditaria","detalle":"Mutación HFE (C282Y homocigoto principalmente) con sobrecarga progresiva de hierro; tríada clásica de cirrosis, diabetes y pigmentación cutánea (\"diabetes bronceada\")."},{"nombre":"Enfermedad de Wilson","detalle":"Mutación ATP7B con alteración del transporte de cobre; ceruloplasmina baja, cobre urinario 24h elevado, anillos de Kayser-Fleischer; puede presentarse como falla hepática fulminante en jóvenes."},{"nombre":"Déficit de alfa-1 antitripsina","detalle":"Mutación del gen SERPINA1 (fenotipo PiZZ el más grave); acumulación de proteína mal plegada en el hepatocito con enfermedad hepática y enfisema pulmonar concomitante."},{"nombre":"Enfermedad vascular hepática","detalle":"Síndrome de Budd-Chiari (obstrucción de venas hepáticas), enfermedad venooclusiva/síndrome de obstrucción sinusoidal, y cirrosis cardiaca por congestión venosa crónica (insuficiencia cardiaca derecha, pericarditis constrictiva)."},{"nombre":"Medicamentos y tóxicos","detalle":"Metotrexato, amiodarona, isoniazida y otros con potencial de daño hepático crónico acumulativo cuando se usan a largo plazo sin vigilancia."},{"nombre":"Otras causas menos frecuentes","detalle":"Cirrosis biliar secundaria (obstrucción biliar crónica), enfermedad celíaca, sarcoidosis hepática, y cirrosis criptogénica (diagnóstico de exclusión, frecuentemente MASH \"quemado\")."}],"factores_riesgo":["Obesidad, diabetes mellitus tipo 2 y síndrome metabólico (MASLD)","Consumo de alcohol de riesgo y patrón binge","Exposición percutánea/sexual a virus hepatotropos (uso de drogas IV, transfusiones previas a 1992, tatuajes no regulados)","Antecedentes familiares de hepatopatía o enfermedades metabólicas hereditarias","Sexo femenino para enfermedades autoinmunes hepáticas","Coinfección VIH-VHC/VHB","Uso crónico de hepatotóxicos sin vigilancia","Enfermedad inflamatoria intestinal (CEP)"]},"fisiopatologia":{"cascada":["Lesión hepatocelular crónica (viral, tóxica, metabólica, autoinmune, colestásica) → necrosis/apoptosis hepatocitaria repetida","Inflamación persistente: reclutamiento de macrófagos residentes (células de Kupffer) y circulantes que liberan citocinas profibrogénicas","Activación de células estrelladas hepáticas (CEH): transdiferenciación de su fenotipo quiescente (rico en vitamina A) a miofibroblastos contráctiles y proliferativos","Producción excesiva de matriz extracelular (colágeno I/III, fibronectina) en el espacio de Disse","Capilarización sinusoidal: pérdida de las fenestraciones endoteliales sinusoidales, con depósito de membrana basal, que altera el intercambio hepatocito-sangre y aumenta la resistencia al flujo","Aumento de la resistencia vascular intrahepática (componente estructural fijo por fibrosis/nódulos + componente funcional dinámico por vasoconstricción intrahepática debida a déficit relativo de óxido nítrico y exceso de endotelina-1)","Hipertensión portal: HVPG >5 mmHg (patológico); >10 mmHg define hipertensión portal clínicamente significativa (HPCS)","Vasodilatación esplácnica progresiva mediada por óxido nítrico y otros vasodilatadores (a diferencia del hígado, aquí hay exceso de NO), que aumenta el flujo sanguíneo esplácnico y portal","Disminución del volumen arterial efectivo (\"underfilling\" arterial) por secuestro esplácnico y vasodilatación sistémica","Activación de sistemas neurohumorales compensadores: sistema renina-angiotensina-aldosterona (SRAA), sistema nervioso simpático y hormona antidiurética (ADH/vasopresina) no osmótica","Retención renal de sodio y agua libre, generando ascitis, edema e hiponatremia dilucional","Estado circulatorio hiperdinámico: gasto cardiaco aumentado, resistencias vasculares sistémicas disminuidas, taquicardia relativa e hipotensión","Progresión a vasodilatación arterial extrema → hipoperfusión renal real → síndrome hepatorrenal como expresión final del deterioro circulatorio","En paralelo, la insuficiencia hepatocelular progresiva reduce síntesis de albúmina y factores de coagulación, y disminuye el clearance de amonio y otras toxinas, favoreciendo encefalopatía hepática"],"mediadores":[{"nombre":"TGF-β (factor de crecimiento transformante beta)","funcion":"Principal citocina profibrogénica; activa CEH y estimula síntesis de colágeno; inhibe su degradación."},{"nombre":"VEGF (factor de crecimiento endotelial vascular)","funcion":"Promueve angiogénesis patológica y formación de colaterales portosistémicas; contribuye a la vasodilatación esplácnica."},{"nombre":"Endotelina-1","funcion":"Potente vasoconstrictor; su receptor ETA predomina en CEH activadas contribuyendo a la vasoconstricción intrahepática (componente dinámico de la HTP)."},{"nombre":"Óxido nítrico (NO)","funcion":"Paradoja fisiopatológica clave: deficiente a nivel intrahepático (contribuye a vasoconstricción sinusoidal) pero en exceso a nivel esplácnico/sistémico (contribuye a vasodilatación y circulación hiperdinámica)."},{"nombre":"TNF-α","funcion":"Citocina proinflamatoria producida por células de Kupffer activadas (frecuentemente por translocación bacteriana desde la luz intestinal); amplifica la inflamación y contribuye a disfunción circulatoria."},{"nombre":"IL-6","funcion":"Mediador de la respuesta de fase aguda; contribuye a la inflamación sistémica crónica (\"inflamación asociada a cirrosis\") y a la disfunción inmune del cirrótico."}]},"diagnostico":{"clinica":{"tituloA":"Cirrosis compensada","tituloB":"Cirrosis descompensada","compensada":"Puede ser asintomática o presentar síntomas inespecíficos (fatiga, anorexia leve, malestar en hipocondrio derecho). Se detecta frecuentemente de forma incidental por hallazgos de laboratorio o imagen, o por estigmas exploratorios sutiles.","descompensada":"Definida por la aparición de al menos un evento de descompensación: ascitis, hemorragia variceal, encefalopatía hepática o ictericia. Marca un punto de inflexión pronóstica con caída marcada de la supervivencia (mediana ~2 años vs. >12 años en compensada).","estigmas":["Arañas vasculares (spider angiomas), típicamente en territorio de vena cava superior","Eritema palmar (thenar/hipotenar)","Ginecomastia y atrofia testicular (hiperestrogenismo relativo por menor clearance hepático de andrógenos aromatizables)","Contractura de Dupuytren (asociación clásica con etiología alcohólica)","Uñas de Terry (leuconiquia proximal con banda distal rosada/marrón) y leuconiquia estriada","Ictericia mucocutánea (bilirrubina >2-3 mg/dL clínicamente visible)","Ascitis y edema de miembros inferiores","Circulación colateral abdominal y caput medusae (recanalización de vena umbilical)","Esplenomegalia (congestiva, por hipertensión portal) y hepatomegalia (variable; el hígado puede estar atrófico en fases avanzadas)","Asterixis (\"flapping tremor\") y alteración del estado mental como signos de encefalopatía hepática","Fetor hepático (olor dulzón por mercaptanos)","Hipertrofia parotídea (asociación alcohólica)"]},"laboratorio":[{"prueba":"Biometría hemática completa","utilidad":"Trombocitopenia como marcador indirecto temprano de hipertensión portal/hiperesplenismo (frecuentemente el primer hallazgo); anemia multifactorial (sangrado crónico, hemólisis, déficit nutricional, hiperesplenismo); leucopenia por secuestro esplénico."},{"prueba":"AST/ALT","utilidad":"Relación AST/ALT >1 sugiere etiología alcohólica o cirrosis ya establecida (pérdida de masa hepatocitaria); elevaciones pueden ser mínimas o normales en cirrosis \"quemada\", por lo que su normalidad NO excluye cirrosis."},{"prueba":"Fosfatasa alcalina y GGT","utilidad":"Elevación predominante sugiere patrón colestásico (CBP, CEP, obstrucción biliar); GGT ayuda a confirmar origen hepático de la FA elevada y se asocia a consumo de alcohol."},{"prueba":"Bilirrubina total y fraccionada","utilidad":"Marcador de función excretora e insuficiencia hepatocelular; componente de Child-Pugh y MELD; su elevación progresiva sin causa obstructiva indica descompensación."},{"prueba":"Albúmina sérica","utilidad":"Refleja capacidad de síntesis hepática (vida media ~20 días, por lo que no cambia agudamente); hipoalbuminemia se correlaciona con severidad y predispone a ascitis."},{"prueba":"INR / tiempo de protrombina / factor V","utilidad":"Los factores de coagulación (excepto VIII) se sintetizan en el hígado; su prolongación refleja insuficiencia de síntesis. El factor V (no dependiente de vitamina K) ayuda a diferenciar insuficiencia hepática de déficit de vitamina K."},{"prueba":"Función renal (urea, creatinina, TFG)","utilidad":"La creatinina sobreestima la función renal real en cirróticos (menor masa muscular); esencial para detectar lesión renal aguda y síndrome hepatorrenal; base para MELD."},{"prueba":"Electrolitos y sodio sérico","utilidad":"La hiponatremia dilucional (<130 mEq/L) es marcador de mal pronóstico y componente de MELD-Na; guía manejo de diuréticos y restricción de líquidos."}],"etiologicos":[{"prueba":"Serologías VHB (HBsAg, anti-HBc, anti-HBs) y VHC (anti-VHC, ARN-VHC)","utilidad":"Confirman infección activa; carga viral y genotipo guían tratamiento antiviral."},{"prueba":"ANA, ASMA (anti-músculo liso), anti-LKM1, IgG","utilidad":"Panel para hepatitis autoinmune; IgG elevada apoya el diagnóstico junto con hallazgos histológicos."},{"prueba":"AMA (anticuerpo antimitocondrial)","utilidad":"Positivo en >90% de CBP; junto con FA elevada permite diagnóstico sin biopsia en la mayoría de los casos."},{"prueba":"Ferritina y saturación de transferrina","utilidad":"Saturación de transferrina >45% es el cribado inicial más sensible para hemocromatosis; ferritina muy elevada apoya sobrecarga de hierro (confirmar con estudio genético HFE)."},{"prueba":"Ceruloplasmina y cobre urinario de 24h","utilidad":"Ceruloplasmina baja (<20 mg/dL) sugiere enfermedad de Wilson; cobre urinario elevado (>100 μg/24h) apoya el diagnóstico, especialmente tras estímulo con D-penicilamina."},{"prueba":"Alfa-1 antitripsina sérica y fenotipo/genotipo","utilidad":"Niveles bajos con fenotipo PiZZ confirman déficit; considerar en cirrosis criptogénica, especialmente con enfisema concomitante."}],"no_invasivos":[{"metodo":"FIB-4","interpretacion":"Índice basado en edad, AST, ALT y plaquetas: [Edad × AST] / [Plaquetas × √ALT].","sens":"—","esp":"—","cutoff":"<1.3 excluye fibrosis avanzada (en >65 años <2.0); >2.67 sugiere fibrosis avanzada/cirrosis; zona gris intermedia requiere estudio adicional."},{"metodo":"APRI","interpretacion":"(AST/límite superior normal × 100) / plaquetas (10⁹/L).","sens":"—","esp":"—","cutoff":">1.0 sugiere cirrosis (validado originalmente en hepatitis C); <0.5 tiene buen valor predictivo negativo."},{"metodo":"Elastografía hepática transitoria (FibroScan)","interpretacion":"Mide la velocidad de propagación de una onda de cizallamiento (correlaciona con rigidez hepática).","sens":"~85%","esp":"~85%","cutoff":"<8 kPa fibrosis significativa improbable; ≥15 kPa altamente sugestivo de cirrosis; el consenso Baveno VII usa LSM <15 kPa + plaquetas >150,000 para descartar HPCS (\"regla del 5\")."},{"metodo":"Elastografía por resonancia magnética (MRE)","interpretacion":"Método no invasivo más preciso disponible; mide rigidez hepática mediante ondas mecánicas y RM.","sens":">90%","esp":">90%","cutoff":">4.7-5 kPa sugiere cirrosis; menos afectado por obesidad y ascitis que el FibroScan."},{"metodo":"FibroTest/otros paneles serológicos","interpretacion":"Combinan biomarcadores séricos (bilirrubina, GGT, apolipoproteína A1, haptoglobina, alfa-2-macroglobulina) en un score patentado.","sens":"~75%","esp":"~85%","cutoff":"Score >0.75 sugiere fibrosis avanzada; útil como alternativa cuando la elastografía no está disponible."}],"imagen":[{"modalidad":"Ultrasonido hepático","hallazgos":"Contorno hepático nodular/irregular, ecotextura heterogénea, atrofia del lóbulo derecho con hipertrofia del izquierdo/caudado, esplenomegalia (>12-13 cm); primera línea por accesibilidad y costo."},{"modalidad":"Doppler portal","hallazgos":"Evalúa permeabilidad y dirección del flujo portal (normal hepatópeto vs. hepatófugo en HTP severa), velocidad de flujo, presencia de colaterales y trombosis portal; congestión esplénica."},{"modalidad":"Tomografía computarizada trifásica","hallazgos":"Superficie nodular, hipertrofia caudada, colaterales portosistémicas (varices esofágicas, gástricas, recanalización umbilical), esplenomegalia; fase arterial y venosa esenciales para caracterizar nódulos sospechosos de HCC (hipervascularidad arterial con lavado venoso)."},{"modalidad":"Resonancia magnética con contraste hepatoespecífico","hallazgos":"Mayor sensibilidad para caracterización de nódulos según criterios LI-RADS; útil en vigilancia de HCC ante hallazgos indeterminados en US/TC."}],"biopsia":{"indicaciones":"Casos con diagnóstico etiológico incierto tras estudio no invasivo completo, sospecha de superposición de etiologías, discordancia entre datos clínicos/serológicos e imagen, o necesidad de gradificar actividad inflamatoria además de fibrosis (p.ej. hepatitis autoinmune, evaluación pre-tratamiento en algunos contextos).","ventajas":"Método de referencia (\"gold standard\") histórico; permite evaluar simultáneamente fibrosis, inflamación, esteatosis y hallazgos específicos de etiología.","limitaciones":"Invasiva, con riesgo de sangrado, dolor y, raramente, mortalidad (~0.01-0.1%); error de muestreo (la fibrosis puede ser heterogénea); variabilidad interobservador; ha sido ampliamente reemplazada por métodos no invasivos para estadificación de fibrosis en la práctica actual.","contraindicaciones":"Coagulopatía significativa no corregida, trombocitopenia severa, ascitis a tensión (relativa, considerar vía transyugular), infección cutánea en el sitio de punción, dilatación de vía biliar no descomprimida."}},"clasificacion":{"compensada_descompensada":"La cirrosis compensada se subdivide en 1a (sin varices) y 1b (con varices, sin sangrado); la descompensada se subdivide en 2a (primera descompensación) y 2b (descompensación múltiple/recurrente), con supervivencias medianas decrecientes en cada subestadio (modelo de estadificación clínica de D'Amico/Baveno VII).","escalas":[{"nombre":"Child-Pugh","componentes":"Bilirrubina, albúmina, INR, ascitis (clínica), encefalopatía (grado clínico); 5 variables, 1-3 puntos cada una.","formula":"Suma de puntos (5-15)","interpretacion":"A (5-6 pts): compensada, supervivencia ~1 año 100%. B (7-9 pts): descompensación significativa. C (10-15 pts): descompensación avanzada, supervivencia ~1 año 45%.","uso":"Pronóstico global, elegibilidad quirúrgica no hepática, clasificación histórica pre-MELD para trasplante."},{"nombre":"MELD","componentes":"Bilirrubina, INR, creatinina (fórmula logarítmica original).","formula":"3.78×ln(bilirrubina) + 11.2×ln(INR) + 9.57×ln(creatinina) + 6.43","interpretacion":"Rango 6-40; mayor puntaje = mayor mortalidad a 90 días.","uso":"Priorización en lista de trasplante hepático (UNOS/OPTN); predicción de mortalidad a corto plazo."},{"nombre":"MELD-Na","componentes":"MELD + sodio sérico (corregido a rango 125-137 mEq/L).","formula":"MELD + 1.32×(137-Na) − [0.033×MELD×(137-Na)]","interpretacion":"Mejora la predicción de mortalidad al incorporar el impacto pronóstico de la hiponatremia; estándar actual para asignación de órganos en muchos sistemas.","uso":"Priorización de trasplante hepático (sistema vigente en EE.UU. desde 2016)."},{"nombre":"CLIF-C ACLF","componentes":"Score CLIF-OF (6 sistemas orgánicos: hígado, riñón, cerebro, coagulación, circulación, pulmón) + edad + leucocitos.","formula":"Fórmula ponderada validada por el consorcio CANONIC/CLIF","interpretacion":"Estratifica ACLF en grados 1-3 según número de fallas orgánicas; predice mortalidad a 28-90 días con mayor precisión que MELD en el contexto agudo.","uso":"Estratificación pronóstica y toma de decisiones en falla hepática aguda sobre crónica, incluyendo priorización urgente para trasplante."},{"nombre":"HVPG (gradiente de presión venosa hepática)","componentes":"Diferencia entre presión venosa hepática enclavada y libre (cateterismo venoso hepático).","formula":"PVH enclavada − PVH libre","interpretacion":">5 mmHg: hipertensión portal. ≥10 mmHg: hipertensión portal clínicamente significativa (HPCS), umbral para riesgo de descompensación y varices. ≥12 mmHg: riesgo de hemorragia variceal y ascitis. ≥16 mmHg y ≥20 mmHg: mayor riesgo de mortalidad y fracaso al tratamiento del sangrado agudo respectivamente.","uso":"Método de referencia para cuantificar hipertensión portal; evalúa respuesta a betabloqueadores no selectivos (BBNS); estratifica riesgo quirúrgico."},{"nombre":"Criterios de Baveno VII — HPCS","componentes":"Combina elastografía hepática (LSM) y recuento plaquetario.","formula":"\"Regla del 5\" y criterios de descarte","interpretacion":"LSM ≥25 kPa: HPCS muy probable sin necesidad de más estudios. LSM <15 kPa + plaquetas ≥150,000: HPCS descartada razonablemente. LSM 15-25 kPa: zona gris, considerar endoscopia o HVPG.","uso":"Guía la decisión de tamizaje endoscópico de varices y necesidad de HVPG."},{"nombre":"SAAG (gradiente de albúmina suero-ascitis)","componentes":"Albúmina sérica menos albúmina en líquido ascítico (muestras simultáneas).","formula":"Albúmina sérica − Albúmina líquido ascítico","interpretacion":"≥1.1 g/dL: hipertensión portal (sensibilidad ~97%). <1.1 g/dL: causas no relacionadas con HTP (carcinomatosis peritoneal, TB peritoneal, pancreatitis, síndrome nefrótico).","uso":"Clasificación etiológica de la ascitis, más útil que la clasificación clásica exudado/trasudado."}]},"complicaciones":[{"nombre":"Hipertensión Portal","color":"#3d5a73","definicion":"Elevación patológica del gradiente de presión venosa hepática (HVPG) por encima de 5 mmHg; es el motor fisiopatológico central de todas las complicaciones de la cirrosis descompensada.","fisiopatologia":"Componente estructural fijo (fibrosis, nódulos, capilarización sinusoidal) que aporta ~70% de la resistencia, más un componente funcional dinámico (déficit de NO intrahepático, exceso de endotelina-1) que aporta ~30% y es parcialmente reversible farmacológicamente.","epidemiologia":"Presente virtualmente en el 100% de la cirrosis; la hipertensión portal clínicamente significativa (HPCS, HVPG ≥10 mmHg) se desarrolla en ~50-60% de los pacientes compensados a 5 años.","factores_riesgo":["Severidad de la fibrosis","Etiología alcohólica activa","Persistencia del agente causal","Componente inflamatorio activo sobreañadido"],"clinica":"Esplenomegalia, circulación colateral (caput medusae), varices esófago-gástricas, ascitis, encefalopatía; en fases subclínicas puede ser asintomática.","criterios_dx":"HVPG >5 mmHg (patológico); ≥10 mmHg define HPCS. Criterios no invasivos de Baveno VII: LSM ≥25 kPa (HPCS probable) o LSM <15 kPa + plaquetas ≥150,000 (HPCS descartada).","laboratorio":"Trombocitopenia (marcador indirecto más sensible), leucopenia por hiperesplenismo.","imagen":"Esplenomegalia, circulación colateral, flujo portal hepatófugo o enlentecido en Doppler, ascitis.","complementarios":"Elastografía hepática (LSM), endoscopia digestiva alta para tamizaje de varices, cateterismo de venas hepáticas para HVPG en casos seleccionados.","dx_diferencial":"Hipertensión portal no cirrótica (trombosis portal, esquistosomiasis, hiperplasia nodular regenerativa, hipertensión portal idiopática), Budd-Chiari.","tx_medico":"Tratamiento etiológico de la hepatopatía de base (abstinencia alcohólica, antivirales, inmunosupresión según causa) para reducir/revertir el componente estructural.","tx_farmacologico":"Betabloqueadores no selectivos (BBNS): propranolol o carvedilol como profilaxis primaria en HPCS/varices; carvedilol preferido por su efecto anti-alfa-1 adicional (mayor reducción de HVPG). Estatinas (simvastatina) en estudio como coadyuvante por efecto pleiotrópico endotelial.","tx_intervencionista":"TIPS en casos seleccionados de HTP severa refractaria a manejo médico con complicaciones recurrentes.","criterios_uci":"No aplica de forma directa salvo por complicaciones asociadas (hemorragia, ACLF).","criterios_tips":"HPCS severa con descompensaciones recurrentes a pesar de tratamiento óptimo (ver criterios específicos por complicación).","criterios_trasplante":"Evaluar en el contexto de descompensación global de la hepatopatía, no como indicación aislada.","seguimiento_hospitalario":"No aplica como entidad aislada; se sigue en el contexto de sus complicaciones.","seguimiento_ambulatorio":"Vigilancia con elastografía y/o endoscopia según Baveno VII; reevaluación de HVPG en centros especializados si disponible tras inicio de BBNS.","pronostico":"El cruce del umbral de HPCS (HVPG ≥10 mmHg) predice descompensación clínica; HVPG ≥16 mmHg se asocia a mayor mortalidad.","algoritmo":["Cirrosis compensada confirmada (clínica + no invasiva)","Evaluar HPCS: LSM + plaquetas (regla de Baveno VII)","LSM ≥25 kPa → HPCS probable → iniciar BBNS o vigilancia endoscópica","LSM <15 kPa + plaquetas ≥150,000 → HPCS descartada → repetir en 1-2 años","Zona gris (15-25 kPa) → endoscopia o HVPG según disponibilidad"]},{"nombre":"Ascitis","color":"#3d6b6b","definicion":"Acumulación patológica de líquido en la cavidad peritoneal; es la complicación más frecuente de la cirrosis descompensada y el evento índice de descompensación más común.","fisiopatologia":"Hipertensión portal sinusoidal + vasodilatación esplácnica → disminución del volumen arterial efectivo → activación de SRAA, sistema simpático y ADH no osmótica → retención renal de sodio y agua → trasudación de líquido rico en proteínas hacia peritoneo (teoría de la vasodilatación arterial periférica).","epidemiologia":"Se desarrolla en ~60% de los pacientes con cirrosis compensada a 10 años; marca el inicio de la fase descompensada con caída de supervivencia mediana a ~2 años.","factores_riesgo":["HVPG ≥12 mmHg","Hipoalbuminemia severa","Hiponatremia","Deterioro de función renal basal"],"clinica":"Distensión abdominal progresiva, aumento de peso, matidez cambiante, signo de la oleada en ascitis a tensión, disnea si hay derrame pleural asociado (hidrotórax hepático), hernias umbilicales.","criterios_dx":"Grado 1 (leve, solo detectable por US), Grado 2 (moderada, distensión simétrica moderada), Grado 3 (a tensión, marcada distensión abdominal) según Club Internacional de Ascitis (ICA).","laboratorio":"Paracentesis diagnóstica obligatoria en toda ascitis de nuevo diagnóstico o ingreso hospitalario: recuento celular con diferencial, albúmina (para SAAG), proteínas totales, cultivo en frascos de hemocultivo a pie de cama.","imagen":"Ultrasonido abdominal como método más sensible para detección (detecta desde ~100 mL); guía la paracentesis.","complementarios":"SAAG ≥1.1 g/dL confirma origen por hipertensión portal; proteínas del líquido ascítico <1.5 g/dL identifica pacientes de mayor riesgo de PBE (candidatos a profilaxis).","dx_diferencial":"Carcinomatosis peritoneal, tuberculosis peritoneal, ascitis pancreática, síndrome nefrótico, insuficiencia cardiaca (SAAG alto pero proteínas totales elevadas), mixedema.","tx_medico":"Restricción de sodio a 2 g/día (~88 mEq); NO restringir líquidos salvo Na <125 mEq/L; evitar AINEs y aminoglucósidos.","tx_farmacologico":"Diuréticos combinados espironolactona + furosemida en proporción 100:40 mg, titulando cada 3-5 días hasta máximo 400/160 mg; meta de pérdida de peso 0.5 kg/día sin edema o 1 kg/día con edema. Vigilar hiperkalemia (espironolactona) e hiponatremia.","tx_intervencionista":"Paracentesis evacuadora terapéutica en ascitis a tensión sintomática, con reposición de albúmina 6-8 g por litro extraído si se retiran >5 litros.","criterios_uci":"Ascitis a tensión con compromiso respiratorio severo o inestabilidad hemodinámica asociada a complicación concurrente (PBE con sepsis, HRS).","criterios_tips":"Se reserva principalmente para ascitis refractaria (ver siguiente apartado).","criterios_trasplante":"Ascitis como marcador de descompensación debe motivar referencia temprana a evaluación de trasplante hepático, independiente de MELD.","seguimiento_hospitalario":"Peso diario, perímetro abdominal, balance hídrico estricto, electrolitos y creatinina cada 48-72h durante titulación diurética, vigilancia de signos de encefalopatía.","seguimiento_ambulatorio":"Control de peso y adherencia a dieta hiposódica, ajuste periódico de diuréticos, laboratorios (electrolitos, función renal) cada 1-3 meses.","pronostico":"Supervivencia ~50% a 2 años tras el desarrollo de ascitis; peor pronóstico si progresa a refractaria o se asocia a hiponatremia/disfunción renal.","algoritmo":["Ascitis de nuevo diagnóstico → paracentesis diagnóstica (celularidad, SAAG, cultivo, proteínas)","SAAG ≥1.1 → origen portal → clasificar grado (1-3)","Grado 1-2 → restricción de sodio + diuréticos combinados escalonados","Grado 3 (a tensión) → paracentesis evacuadora + albúmina + inicio de diuréticos","Proteínas <1.5 g/dL + disfunción renal/hepática avanzada → profilaxis antibiótica de PBE","Evaluar respuesta a 1 semana; si no respuesta a dosis máximas → reclasificar como refractaria"]},{"nombre":"Ascitis Refractaria","color":"#2d5f5f","definicion":"Ascitis que no puede movilizarse o cuya recurrencia precoz no puede prevenirse adecuadamente con tratamiento médico (dieta + dosis máximas de diuréticos), según criterios del Club Internacional de Ascitis.","fisiopatologia":"Representa el estadio final del deterioro circulatorio: vasodilatación esplácnica extrema con activación neurohumoral máxima, refractaria a la natriuresis inducida por diuréticos, con frecuente deterioro concomitante de la función renal.","epidemiologia":"Ocurre en ~10% de los pacientes con ascitis; se subdivide en resistente a diuréticos (falta de respuesta a dosis máximas) y no manejable por diuréticos (intolerancia por complicaciones: hiperkalemia, lesión renal, hiponatremia, encefalopatía).","factores_riesgo":["Hiponatremia dilucional severa","Disfunción renal basal","Hipotensión arterial","PBE previa"],"clinica":"Ascitis recurrente a pesar de tratamiento óptimo, requerimiento de paracentesis evacuadoras seriadas frecuentes (cada 2-4 semanas), intolerancia a diuréticos.","criterios_dx":"Falta de respuesta a restricción de sodio + dosis máximas de diuréticos (400 mg espironolactona/160 mg furosemida) durante ≥1 semana, o recurrencia rápida (grado 2-3 en <4 semanas), o desarrollo de complicaciones inducidas por diuréticos (encefalopatía, creatinina >2 mg/dL, Na <125 o K >6 mEq/L, ginecomastia dolorosa).","laboratorio":"Electrolitos y función renal seriados; frecuente hiponatremia y elevación progresiva de creatinina.","imagen":"Ultrasonido para confirmar volumen y descartar loculaciones o causas alternativas.","complementarios":"Evaluación de elegibilidad para TIPS (función hepática, edad, comorbilidad cardiopulmonar); MELD-Na para pronóstico.","dx_diferencial":"Ascitis maloadherida a tratamiento por incumplimiento dietético o farmacológico (\"pseudo-refractaria\"), que debe descartarse antes de etiquetar como verdadera refractaria.","tx_medico":"Suspender diuréticos si causan complicaciones; mantener restricción de sodio; manejo nutricional especializado.","tx_farmacologico":"Considerar midodrina como vasoconstrictor coadyuvante en algunos casos para mejorar volumen arterial efectivo y permitir reintroducción de diuréticos.","tx_intervencionista":"Paracentesis evacuadoras seriadas con reposición de albúmina como manejo estándar; TIPS como tratamiento de elección en candidatos apropiados (mejora control de ascitis y supervivencia libre de trasplante vs. paracentesis seriadas en metaanálisis).","criterios_uci":"Descompensación aguda asociada (PBE, HRS, encefalopatía severa post-TIPS).","criterios_tips":"Child-Pugh <12, bilirrubina <5 mg/dL, sin encefalopatía severa previa, sin disfunción cardiaca (evaluar con ecocardiograma), sin HTP portopulmonar severa; edad <70 años favorable.","criterios_trasplante":"La ascitis refractaria por sí sola es indicación de referencia urgente a evaluación de trasplante hepático, independientemente del MELD calculado (\"excepción\" funcional por impacto en calidad de vida y mortalidad).","seguimiento_hospitalario":"Vigilancia post-paracentesis de gran volumen (hipotensión, disfunción circulatoria post-paracentesis), función renal tras reposición de albúmina.","seguimiento_ambulatorio":"Programa de paracentesis evacuadoras programadas si no candidato a TIPS; seguimiento estrecho en clínica de trasplante.","pronostico":"Supervivencia mediana ~6 meses sin trasplante; TIPS mejora supervivencia libre de trasplante comparado con paracentesis seriadas en pacientes seleccionados.","algoritmo":["Ascitis que no responde a dosis máximas de diuréticos o causa complicaciones","Descartar pseudo-refractariedad (adherencia, AINEs, exceso de sodio dietético)","Confirmar criterios ICA de ascitis refractaria","Evaluar elegibilidad para TIPS (función hepática, cardiopulmonar)","Candidato a TIPS → colocación de TIPS","No candidato → paracentesis evacuadoras seriadas + albúmina","Referencia paralela a evaluación de trasplante hepático"]},{"nombre":"Peritonitis Bacteriana Espontánea (PBE)","color":"#5c4a73","definicion":"Infección del líquido ascítico en ausencia de un foco intraabdominal quirúrgicamente tratable, típicamente monomicrobiana, secundaria a translocación bacteriana intestinal.","fisiopatologia":"Sobrecrecimiento bacteriano intestinal + aumento de permeabilidad de la mucosa por congestión venosa + disfunción del sistema inmune (menor actividad opsonizante del líquido ascítico con proteínas <1.5 g/dL) permiten la translocación de bacterias entéricas (predominantemente gramnegativas: E. coli, Klebsiella) a través de ganglios linfáticos mesentéricos hacia el líquido ascítico.","epidemiologia":"Incidencia ~1.5-3.5% por año en pacientes ambulatorios y hasta 10% en hospitalizados con ascitis; mortalidad intrahospitalaria 10-20%.","factores_riesgo":["Proteínas del líquido ascítico <1.5 g/dL","PBE previa (recurrencia hasta 70% al año sin profilaxis)","Hemorragia digestiva variceal activa","Bilirrubina sérica elevada","Disfunción renal"],"clinica":"Puede ser asintomática hasta en 1/3 de los casos; fiebre, dolor abdominal difuso, rebote positivo, empeoramiento de ascitis, encefalopatía de nuevo inicio o deterioro renal inexplicado como única manifestación.","criterios_dx":"Recuento de polimorfonucleares (PMN) en líquido ascítico ≥250 células/mm³ (criterio diagnóstico independiente del cultivo).","laboratorio":"Paracentesis con recuento celular diferencial obligatoria en todo paciente cirrótico hospitalizado con ascitis (independientemente de síntomas); cultivo en frascos de hemocultivo inoculados a pie de cama (sensibilidad ~80% vs. <50% con métodos convencionales); hemocultivos periféricos.","imagen":"TC abdominal solo si se sospecha foco secundario (perforación, absceso) por PMN muy elevados, polimicrobiano, o falta de respuesta al tratamiento.","complementarios":"Diferenciar de ascitis bacteriana neutrocítica con cultivo negativo (mismo manejo que PBE) y bacterascitis monomicrobiana no neutrocítica (PMN <250 con cultivo positivo; requiere repetir paracentesis, tratar si hay síntomas).","dx_diferencial":"Peritonitis bacteriana secundaria (perforación de víscera hueca): sospechar si PMN muy elevados, cultivo polimicrobiano, glucosa baja, LDH elevada, proteínas totales >1 g/dL — requiere TC y valoración quirúrgica urgente.","tx_medico":"Suspender betabloqueadores no selectivos durante el episodio agudo si hay inestabilidad hemodinámica o disfunción renal (controversial, individualizar).","tx_farmacologico":"Cefalosporina de 3ª generación (cefotaxima 2 g IV c/8h o ceftriaxona 2 g IV c/24h) empírica 5-7 días; en PBE nosocomial o con factores de riesgo de multirresistencia considerar piperacilina-tazobactam o carbapenémico según epidemiología local. Albúmina IV 1.5 g/kg el día 1 y 1 g/kg el día 3 en pacientes con creatinina >1 mg/dL, BUN >30 mg/dL o bilirrubina >4 mg/dL (reduce incidencia de síndrome hepatorrenal y mortalidad).","tx_intervencionista":"No aplica salvo sospecha de peritonitis secundaria (manejo quirúrgico).","criterios_uci":"Sepsis/choque séptico, disfunción renal aguda severa, encefalopatía grado III-IV asociada, falla respiratoria concomitante.","criterios_tips":"No indicado en el episodio agudo de PBE.","criterios_trasplante":"Un episodio de PBE debe motivar referencia a evaluación de trasplante hepático dado el mal pronóstico a mediano plazo.","seguimiento_hospitalario":"Repetir paracentesis a las 48h si mala evolución clínica para confirmar reducción de PMN ≥25%; vigilancia de función renal diaria.","seguimiento_ambulatorio":"Profilaxis secundaria indefinida con norfloxacino 400 mg/día o ciprofloxacino/trimetoprim-sulfametoxazol (reduce recurrencia de ~70% a <20% al año); profilaxis primaria en proteínas <1.5 g/dL con disfunción renal/hepática o en hemorragia variceal aguda (ceftriaxona IV seguida de norfloxacino oral).","pronostico":"Mortalidad intrahospitalaria 10-20%; supervivencia a 1 año post-episodio ~30-50% sin trasplante; es uno de los principales precipitantes de ACLF.","algoritmo":["Todo cirrótico con ascitis + fiebre, dolor abdominal, encefalopatía nueva o deterioro renal → paracentesis diagnóstica","PMN ≥250/mm³ → iniciar cefalosporina 3ª generación empírica + albúmina IV si criterios","PMN <250 + cultivo positivo → bacterascitis, repetir paracentesis, tratar si sintomático","Sospecha de causa secundaria (polimicrobiano, PMN muy alto, no respuesta) → TC + valoración quirúrgica","Reevaluar a 48h; sin mejoría → escalar antibiótico y descartar foco secundario","Al alta → profilaxis secundaria indefinida con quinolona"]},{"nombre":"Várices Esofágicas y Gástricas","color":"#8c3a34","definicion":"Dilataciones venosas portosistémicas colaterales que se desarrollan en esófago distal y/o estómago proximal como consecuencia directa de la hipertensión portal, sitio predominante de sangrado digestivo alto en el cirrótico.","fisiopatologia":"Cuando el HVPG supera ~10 mmHg se favorece la apertura y dilatación progresiva de colaterales portosistémicas preexistentes (venas gástricas cortas, plexo submucoso esofágico) impulsada por VEGF y flujo esplácnico aumentado; el riesgo de ruptura se relaciona con el tamaño, la presión intravaricosa y signos de la pared (\"red wale marks\", manchas rojo cereza).","epidemiologia":"Presentes en ~30-40% de cirróticos compensados y ~60% de descompensados al diagnóstico; progresan de pequeñas a grandes a una tasa de ~8% por año.","factores_riesgo":["Severidad de la hepatopatía (Child B/C)","HVPG elevado","Consumo activo de alcohol","Tamaño varicoso grande y signos rojos endoscópicos"],"clinica":"Asintomáticas hasta el sangrado; su hallazgo suele ser endoscópico en el tamizaje.","criterios_dx":"Clasificación endoscópica por tamaño (pequeñas <5 mm, grandes ≥5 mm) y presencia de signos de color rojo; várices gástricas clasificadas según Sarin (GOV1, GOV2, IGV1, IGV2).","laboratorio":"No aplica de forma directa; relevante el contexto de Child-Pugh/MELD.","imagen":"Angio-TC en casos de várices gástricas complejas o shunts espontáneos gastrorrenales para planeación de manejo endovascular.","complementarios":"Criterios de Baveno VII: en pacientes con LSM <20 kPa y plaquetas >150,000 se puede diferir la endoscopia de tamizaje (bajo riesgo de varices grandes).","dx_diferencial":"Otras causas de dilatación venosa submucosa (raras): hipertensión portal no cirrótica de cualquier causa.","tx_medico":"Corrección de factores precipitantes de descompensación; abstinencia alcohólica.","tx_farmacologico":"Profilaxis primaria en varices pequeñas con factores de alto riesgo o grandes: BBNS (propranolol, nadolol o carvedilol) titulado a frecuencia cardiaca 55-60 lpm o dosis máxima tolerada; carvedilol de elección por mayor reducción de HVPG.","tx_intervencionista":"Ligadura endoscópica con bandas (LEB) como alternativa o complemento a BBNS en profilaxis primaria de varices grandes, especialmente si contraindicación/intolerancia a BBNS; para várices gástricas GOV2/IGV1 considerar cianoacrilato.","criterios_uci":"No aplica hasta que ocurra sangrado activo.","criterios_tips":"No indicado en profilaxis primaria; reservado para sangrado agudo/recurrente.","criterios_trasplante":"Evaluar en contexto de descompensación global.","seguimiento_hospitalario":"No aplica como entidad aislada compensada.","seguimiento_ambulatorio":"Vigilancia endoscópica: si no hay varices y LSM/plaquetas no cumplen criterio de bajo riesgo, repetir en 2-3 años (compensada) o 1 año si hay daño hepático continuo; varices pequeñas sin BBNS, repetir en 1-2 años; tras erradicación por LEB, primera revisión a 1-3 meses, luego cada 6-12 meses.","pronostico":"El desarrollo de varices grandes sin profilaxis conlleva riesgo de sangrado ~15% al año.","algoritmo":["Diagnóstico de cirrosis compensada → evaluar criterios de Baveno VII para diferir endoscopia","No cumple criterios de bajo riesgo → endoscopia de tamizaje","Sin varices → repetir en 2-3 años","Varices pequeñas sin factores de riesgo → BBNS o vigilancia; con factores de riesgo (Child B/C, signos rojos) → BBNS","Varices grandes → BBNS o ligadura endoscópica con bandas (elección según disponibilidad/preferencia, no combinar de rutina en profilaxis primaria)"]},{"nombre":"Hemorragia Digestiva por Várices","color":"#7a2e2e","definicion":"Emergencia médica definida como sangrado activo proveniente de várices esofágicas o gástricas, la complicación de mayor mortalidad aguda de la hipertensión portal.","fisiopatologia":"Ruptura de la pared varicosa por presión intravaricosa elevada (relacionada con HVPG y tamaño/tensión de pared según ley de Laplace); el sangrado agudo puede precipitar hipovolemia, hipoperfusión renal (HRS-AKI), translocación bacteriana e infecciones (PBE), y descompensación aguda sobre crónica (ACLF).","epidemiologia":"Mortalidad a 6 semanas ~10-20% a pesar de los avances terapéuticos; riesgo de resangrado precoz (72h-5 días) hasta 30-40% sin manejo adecuado.","factores_riesgo":["HVPG >20 mmHg (predictor de fracaso terapéutico)","Child-Pugh C","Infección bacteriana concomitante","Trombosis portal","Carcinoma hepatocelular"],"clinica":"Hematemesis, melena, hematoquecia si sangrado masivo, signos de choque hipovolémico, encefalopatía precipitada por la carga proteica intestinal de la sangre digerida.","figura":"farmacos-vasoactivos-variceal","criterios_dx":"Confirmación endoscópica de sangrado activo (a chorro o en sábana), estigmas de sangrado reciente (coágulo adherido, vaso visible) o presencia de varices sin otra fuente identificable en contexto clínico compatible.","laboratorio":"Hemoglobina/hematocrito (pueden no reflejar la magnitud real del sangrado en las primeras horas por hemoconcentración), pruebas cruzadas, INR, función renal, lactato.","imagen":"Endoscopia digestiva alta como estudio diagnóstico y terapéutico de elección, idealmente dentro de las primeras 12h tras estabilización hemodinámica.","complementarios":"Angio-TC si endoscopia no logra localizar/controlar el sitio en sangrado masivo, para planear manejo endovascular de rescate.","dx_diferencial":"Úlcera péptica, gastropatía hipertensiva portal, síndrome de Mallory-Weiss, ectasia vascular antral gástrica (GAVE), neoplasia.","tx_medico":"Reanimación con cristaloides de forma restrictiva, transfusión de hemoderivados con meta de hemoglobina ~7-8 g/dL (estrategia restrictiva, evitar sobretransfusión que aumenta presión portal), protección de vía aérea si alteración del estado de conciencia o hematemesis masiva, intubación orotraqueal previa a endoscopia si riesgo de aspiración.","tx_farmacologico":"Fármacos vasoactivos iniciados lo antes posible (idealmente prehospitalario/al ingreso): terlipresina, octreótide o somatostatina, mantenidos 2-5 días. Antibiótico profiláctico obligatorio en todo paciente con hemorragia variceal (ceftriaxona 1 g IV/24h, o norfloxacino oral si bajo riesgo) independientemente de la presencia de ascitis, ya que reduce mortalidad y resangrado. Corrección de coagulopatía solo si INR muy elevado o sangrado no controlado (no de rutina).","tx_intervencionista":"Ligadura endoscópica con bandas para varices esofágicas (elección); inyección de cianoacrilato para varices gástricas (GOV2/IGV1); balón de Sengstaken-Blakemore/Minnesota como puente temporal en sangrado masivo no controlable endoscópicamente; TIPS de rescate en sangrado refractario.","criterios_uci":"Inestabilidad hemodinámica, requerimiento de vasopresores, protección de vía aérea, Child-Pugh C, alto riesgo de resangrado o falla terapéutica.","criterios_tips":"TIPS precoz (\"early/pre-emptive TIPS\") dentro de 24-72h en pacientes de alto riesgo (Child-Pugh C <14 puntos o Child-Pugh B con sangrado activo en la endoscopia) — reduce resangrado y mortalidad vs. manejo endoscópico estándar de rescate. TIPS de rescate en fracaso del tratamiento endoscópico/farmacológico combinado.","criterios_trasplante":"Todo episodio de hemorragia variceal, especialmente si Child-Pugh C, debe motivar referencia a evaluación de trasplante hepático.","seguimiento_hospitalario":"Vigilancia hemodinámica estrecha, hemoglobina seriada, vigilancia de encefalopatía, function renal diaria, profilaxis de PBE, iniciar lactulosa si signos de encefalopatía.","seguimiento_ambulatorio":"Profilaxis secundaria combinada obligatoria: BBNS (carvedilol o propranolol) + ligadura endoscópica con bandas seriada hasta erradicación (estándar de mayor eficacia que cualquiera de las dos modalidades aislada); vigilancia endoscópica post-erradicación.","pronostico":"Mortalidad a 6 semanas 10-20%; TIPS precoz en pacientes de alto riesgo reduce mortalidad a 1 año de forma significativa.","algoritmo":["Sospecha de hemorragia digestiva alta variceal → reanimación (vía aérea, dos accesos IV, cristaloides restrictivos)","Iniciar vasoactivo (terlipresina/octreótide/somatostatina) + antibiótico profiláctico (ceftriaxona) de inmediato","Transfusión restrictiva (meta Hb 7-8 g/dL)","Endoscopia diagnóstico-terapéutica en <12h: ligadura con bandas (esofágicas) o cianoacrilato (gástricas)","Evaluar riesgo alto (Child-Pugh C <14 o Child B + sangrado activo) → TIPS precoz en 24-72h","Sangrado no controlado/masivo → balón de taponamiento como puente → TIPS de rescate","Control → mantener vasoactivo 2-5 días + iniciar profilaxis secundaria combinada (BBNS + LEB) antes del alta"]},{"nombre":"Gastropatía Hipertensiva Portal","color":"#966b35","definicion":"Alteración de la mucosa gástrica (predominantemente fúndica/corporal) secundaria a congestión venosa y capilar por hipertensión portal, con aspecto endoscópico característico en \"mosaico\" o \"piel de serpiente\".","fisiopatologia":"Congestión vascular de la mucosa y submucosa gástrica con dilatación capilar y venular, sin inflamación significativa (a diferencia de la gastritis); puede causar sangrado crónico oculto o, con menor frecuencia, agudo.","epidemiologia":"Presente en 20-98% de cirróticos según definición endoscópica utilizada; más frecuente y severa en pacientes con varices grandes o tratados previamente con escleroterapia.","factores_riesgo":["Severidad de la hipertensión portal","Antecedente de escleroterapia endoscópica","Varices de gran tamaño"],"clinica":"Habitualmente asintomática; puede manifestarse como anemia ferropénica crónica por pérdidas ocultas o, en su forma severa, hematemesis/melena.","criterios_dx":"Clasificación endoscópica en leve (patrón en mosaico) y severa (puntos rojos, manchas marrón-negruzcas, sangrado difuso).","laboratorio":"Anemia ferropénica en la forma crónica; ferritina baja, hierro sérico bajo.","imagen":"No requiere imagen adicional; diagnóstico endoscópico.","complementarios":"Diferenciar de ectasia vascular antral gástrica (GAVE, \"watermelon stomach\"), entidad distinta que no mejora con reducción de presión portal.","dx_diferencial":"GAVE, gastritis erosiva, úlcera péptica.","tx_medico":"Suplementación con hierro oral o IV según severidad de la anemia.","tx_farmacologico":"BBNS (propranolol/carvedilol) como tratamiento de elección, ya que reduce la presión portal y el sangrado crónico/agudo asociado.","tx_intervencionista":"TIPS en casos de sangrado severo recurrente refractario a BBNS (poco frecuente).","criterios_uci":"Solo en sangrado agudo severo con inestabilidad hemodinámica.","criterios_tips":"Sangrado crónico transfusión-dependiente refractario a BBNS.","criterios_trasplante":"Evaluar en contexto de descompensación global de la hepatopatía.","seguimiento_hospitalario":"Vigilancia de hemoglobina si sangrado activo.","seguimiento_ambulatorio":"Control de hemoglobina y ferritina periódico; ajuste de dosis de BBNS.","pronostico":"Generalmente causa anemia crónica manejable; el sangrado agudo severo es infrecuente pero puede ser grave.","algoritmo":["Anemia crónica o sangrado en cirrótico → endoscopia alta","Patrón en mosaico/puntos rojos confirmatorio → clasificar leve vs. severa","Iniciar BBNS + suplementación de hierro","Sangrado agudo severo → manejo como hemorragia digestiva alta + BBNS","Refractario → considerar TIPS"]},{"nombre":"Síndrome Hepatorrenal (SHR)","color":"#4a4a7a","definicion":"Forma funcional (potencialmente reversible) de lesión renal aguda en el paciente cirrótico con ascitis, resultante de vasoconstricción renal extrema secundaria a disfunción circulatoria avanzada, en ausencia de daño estructural renal significativo.","fisiopatologia":"Estadio final del \"underfilling\" arterial: vasodilatación esplácnica extrema + circulación hiperdinámica sistémica agotan los mecanismos compensadores (SRAA, sistema simpático, ADH), generando vasoconstricción renal intensa e hipoperfusión, frecuentemente precipitada por PBE u otra infección, hemorragia digestiva, o paracentesis de gran volumen sin reposición adecuada de albúmina.","epidemiologia":"Se desarrolla en ~20% de pacientes con ascitis a 5 años; la nomenclatura actual (consenso ICA/IAC 2015 y revisión 2019) reemplazó SHR tipo 1 por HRS-AKI y SHR tipo 2 por HRS-NAKI (non-AKI, forma crónica).","factores_riesgo":["PBE u otra infección bacteriana","Hemorragia digestiva","Paracentesis de gran volumen sin albúmina","Uso de AINEs","Ascitis refractaria previa"],"clinica":"Oliguria progresiva, ausencia de otros signos de daño renal estructural (sedimento urinario blando, sin hematuria significativa), frecuentemente en contexto de descompensación aguda multiorgánica.","criterios_dx":"Criterios ICA-AKI: aumento de creatinina ≥0.3 mg/dL en 48h o ≥50% respecto a basal en 7 días, en paciente con cirrosis y ascitis, tras exclusión de: choque, nefrotóxicos actuales/recientes, ausencia de mejoría tras 2 días de suspensión de diuréticos y expansión con albúmina 1 g/kg (máx. 100 g/día), ausencia de signos de daño estructural (proteinuria >500 mg/día, hematuria >50 eritrocitos/campo, alteraciones ecográficas renales).","laboratorio":"Creatinina seriada, electrolitos urinarios (sodio urinario típicamente muy bajo <10 mEq/L reflejando avidez renal de sodio), sedimento urinario sin alteraciones significativas, relación proteína/creatinina urinaria normal.","imagen":"Ultrasonido renal para descartar uropatía obstructiva u otra causa estructural (obligatorio para el diagnóstico).","complementarios":"Biomarcadores emergentes (NGAL urinario) para diferenciar de necrosis tubular aguda en casos dudosos (no disponibles universalmente).","dx_diferencial":"Necrosis tubular aguda (nefrotóxicos, sepsis prolongada, sedimento con cilindros granulosos), lesión renal aguda prerrenal por hipovolemia real (responde a volumen), glomerulopatías asociadas a hepatopatía (nefropatía IgA, glomerulonefritis membranoproliferativa en VHC/VHB), nefritis intersticial por fármacos.","tx_medico":"Suspender diuréticos y nefrotóxicos (AINEs, aminoglucósidos, IECA/ARA2); expansión de volumen con albúmina IV 1 g/kg/día (máx. 100 g/día) por 2 días como prueba diagnóstico-terapéutica inicial; tratar el factor precipitante (antibióticos si infección).","tx_farmacologico":"Terlipresina (vasoconstrictor esplácnico de elección) combinada con albúmina IV es el tratamiento de primera línea para HRS-AKI. Dosis de terlipresina: bolos IV de 0.5-1 mg cada 4-6h, incrementando a 2 mg cada 4-6h si la creatinina no desciende ≥25% a las 48-72h, hasta un máximo de 12 mg/día; alternativa en infusión continua iniciando en 2 mg/día con incrementos cada 2 días hasta el mismo máximo (menor tasa de eventos adversos isquémicos que los bolos). Mantener hasta reversión completa (creatinina <1.5 mg/dL) o un máximo habitual de 14 días; suspender si no hay respuesta tras 3 días con la dosis máxima. Albúmina IV concomitante: 1 g/kg (máx. 100 g) el día 1, seguida de 20-40 g/día según respuesta clínica y estado de volumen. Contraindicaciones de terlipresina: cardiopatía isquémica no controlada, enfermedad vascular periférica grave, asma grave no controlada. Alternativa donde no esté disponible: noradrenalina en infusión continua 0.5-3 mg/h (0.1-0.7 mcg/kg/min), titulada a un incremento de PAM ≥15 mmHg (requiere UCI/unidad de cuidados intermedios), combinada con la misma pauta de albúmina; midodrina + octreótide + albúmina como opción de menor eficacia si no hay acceso a las anteriores.","tx_intervencionista":"TIPS en casos seleccionados de HRS-NAKI (forma crónica) sin respuesta a vasoconstrictores y con función hepática preservada; terapia de reemplazo renal como puente a trasplante en falla renal severa refractaria o sobrecarga de volumen/hiperkalemia que ponen en riesgo la vida.","criterios_uci":"Uso de noradrenalina, inestabilidad hemodinámica, necesidad de terapia de reemplazo renal, ACLF asociado con falla de ≥2 órganos.","criterios_tips":"HRS-NAKI (crónico) refractario a vasoconstrictores en pacientes con función hepática relativamente preservada (no aplica de rutina en HRS-AKI agudo grave).","criterios_trasplante":"El trasplante hepático (aislado o combinado hepatorrenal si diálisis >4-6 semanas o TFG muy deteriorada de forma sostenida) es el tratamiento definitivo; debe priorizarse la evaluación urgente en todo HRS-AKI que no responde a vasoconstrictores.","seguimiento_hospitalario":"Creatinina diaria, diuresis horaria, vigilancia de sobrecarga de volumen y electrolitos durante infusión de albúmina/terlipresina, monitorización cardiovascular por riesgo de isquemia con terlipresina.","seguimiento_ambulatorio":"Seguimiento nefrológico conjunto si persiste disfunción renal tras reversión parcial; referencia prioritaria a programa de trasplante.","pronostico":"Sin tratamiento, mortalidad de HRS-AKI grave >50% en semanas; con terlipresina + albúmina, tasas de reversión ~40-50%; el trasplante hepático oportuno es lo único que ofrece supervivencia a largo plazo.","algoritmo":["Cirrótico con ascitis + aumento de creatinina cumpliendo criterios ICA-AKI","Suspender diuréticos/nefrotóxicos, descartar choque e infección activa (tratar si presente)","Prueba con albúmina IV 1 g/kg/día × 2 días","Sin respuesta + ecografía renal normal + sedimento sin datos estructurales → diagnóstico de HRS-AKI","Iniciar terlipresina + albúmina (o noradrenalina + albúmina en UCI si no disponible terlipresina)","Respuesta → continuar hasta reversión completa o máx. 14 días","No respuesta → considerar TRR como puente + evaluación urgente de trasplante hepático"]},{"nombre":"Encefalopatía Hepática (EH)","color":"#7a4363","definicion":"Disfunción cerebral causada por insuficiencia hepática y/o cortocircuitos portosistémicos, que se manifiesta como un espectro de alteraciones neuropsiquiátricas y motoras potencialmente reversibles.","fisiopatologia":"Acumulación de amonio (por menor clearance hepático urea-ciclo y mayor derivación portosistémica) que cruza la barrera hematoencefálica y es metabolizado por los astrocitos a glutamina, generando edema astrocitario de bajo grado; contribuyen sinergísticamente neuroinflamación sistémica (citocinas), alteración del eje GABA-benzodiacepinas endógenas, manganeso y desequilibrio de aminoácidos aromáticos/ramificados.","epidemiologia":"EH manifiesta ocurre en 30-40% de los cirróticos en algún momento de su evolución; la EH mínima/encubierta (sin alteración clínica evidente pero con déficit en pruebas psicométricas) afecta hasta 50-80% y se asocia a mayor riesgo de accidentes y progresión a EH manifiesta.","factores_riesgo":["Infecciones (PBE, ITU, neumonía)","Hemorragia digestiva","Estreñimiento","Deshidratación/uso excesivo de diuréticos","Trastornos electrolíticos (hipokalemia, hiponatremia)","Sedantes/benzodiacepinas","Insuficiencia renal","TIPS"],"clinica":"Espectro desde alteración sutil de la atención/concentración hasta coma; asterixis en grados II-III; alteración del ciclo sueño-vigilia; cambios de personalidad; desorientación temporoespacial.","criterios_dx":"Clasificación de West Haven: Grado 0 (normal), Mínima (EHM, solo detectable por pruebas psicométricas/neurofisiológicas), Grado I (euforia/ansiedad leve, disminución de atención, alteración del sueño), Grado II (letargia, desorientación temporal, cambios de personalidad, asterixis presente), Grado III (somnolencia marcada a semiestupor, confusión, desorientación grosera), Grado IV (coma, sin respuesta a estímulos verbales/dolorosos). Clasificación ISHEN complementaria (encubierta vs. manifiesta).","laboratorio":"Amonio sérico: apoya el diagnóstico si elevado pero NO es necesario para el diagnóstico clínico ni se correlaciona linealmente con la severidad; su normalidad debe hacer reconsiderar el diagnóstico. Descartar factores precipitantes: electrolitos, función renal, biometría hemática, paracentesis si ascitis.","imagen":"TC/RM cerebral para excluir diagnósticos diferenciales (hemorragia, ACV, masa) especialmente en primer episodio, focalidad neurológica o falta de respuesta al tratamiento; no es diagnóstica de EH per se.","complementarios":"Pruebas psicométricas (PHES) o neurofisiológicas (tiempo de latencia crítica de parpadeo) para EH mínima; electroencefalograma en casos atípicos.","dx_diferencial":"Delirium por otra causa, intoxicación/abstinencia alcohólica, hemorragia o infarto intracraneal, encefalopatía de Wernicke, trastornos metabólicos (hipoglucemia, uremia), meningoencefalitis, estado epiléptico no convulsivo.","tx_medico":"Identificación y corrección activa del factor precipitante (paso más importante del manejo); protección de vía aérea en grado III-IV; evitar sedantes/benzodiacepinas.","tx_farmacologico":"Lactulosa oral o por sonda (dosis titulada a 2-3 evacuaciones blandas/día) como primera línea, actúa acidificando la luz colónica y como laxante osmótico reduciendo la absorción de amonio; enemas de lactulosa en EH severa/íleo. Rifaximina 550 mg c/12h añadida a lactulosa para prevención secundaria de recurrencia (reduce hospitalizaciones); L-ornitina L-aspartato (LOLA) como coadyuvante en algunos contextos.","tx_intervencionista":"Reducción/oclusión de shunts portosistémicos espontáneos grandes en EH recurrente refractaria a manejo médico óptimo, en centros especializados.","criterios_uci":"Grado III-IV (riesgo de compromiso de vía aérea), necesidad de intubación, falta de respuesta a manejo inicial, ACLF asociado.","criterios_tips":"La EH es una contraindicación relativa/complicación esperada del TIPS, no una indicación; EH recurrente post-TIPS puede requerir reducción del diámetro del stent.","criterios_trasplante":"EH recurrente o persistente a pesar de tratamiento óptimo es indicación de referencia a evaluación de trasplante hepático, con posible asignación de puntos de excepción en algunos sistemas.","seguimiento_hospitalario":"Evaluación neurológica seriada (escala de West Haven), conteo de evacuaciones, corrección de electrolitos, vigilancia de vía aérea en grados avanzados.","seguimiento_ambulatorio":"Continuar lactulosa/rifaximina de mantenimiento tras el primer episodio manifiesto; evaluación de EH mínima si síntomas cognitivos sutiles o dificultad para conducir/trabajar; educación a cuidadores sobre signos de alarma.","pronostico":"Cada episodio de EH manifiesta se asocia a mayor mortalidad y riesgo de recurrencia; la EH mínima no tratada afecta significativamente la calidad de vida y seguridad vial.","algoritmo":["Alteración del estado mental en cirrótico → descartar causas alternativas (imagen cerebral, glucosa, electrolitos)","Confirmar EH → clasificar grado West Haven","Buscar y corregir activamente el factor precipitante (infección, sangrado, estreñimiento, fármacos, disionías)","Iniciar/optimizar lactulosa titulada a 2-3 evacuaciones/día","Grado III-IV → proteger vía aérea, manejo en UCI","Recurrencia a pesar de lactulosa → añadir rifaximina","Recurrencia refractaria → evaluar shunts portosistémicos espontáneos y referencia a trasplante"]},{"nombre":"Síndrome Hepatopulmonar (SHP)","color":"#3f6b52","definicion":"Tríada de enfermedad hepática, dilataciones vasculares intrapulmonares y alteración de la oxigenación arterial (gradiente alveolo-arterial de oxígeno aumentado), independiente de enfermedad cardiopulmonar primaria.","fisiopatologia":"Producción hepática/esplácnica excesiva de óxido nítrico y otros vasodilatadores (que evaden el metabolismo hepático por shunting) alcanza la circulación pulmonar y provoca vasodilatación capilar y precapilar difusa, generando desequilibrio ventilación-perfusión y shunt funcional derecha-izquierda con hipoxemia.","epidemiologia":"Presente en 10-30% de los candidatos a trasplante hepático evaluados; puede ocurrir con cualquier grado de disfunción hepática, incluso hipertensión portal no cirrótica.","factores_riesgo":["Severidad de la hipertensión portal","Presencia de otras complicaciones vasculares (arañas vasculares cutáneas como marcador asociado)"],"clinica":"Disnea de esfuerzo progresiva, platipnea (disnea que empeora al sentarse/pararse) y ortodeoxia (desaturación al pasar de decúbito a bipedestación) son característicos por redistribución del flujo hacia las bases pulmonares donde predominan las dilataciones vasculares.","criterios_dx":"Triada: 1) enfermedad hepática/hipertensión portal, 2) gradiente alveolo-arterial de O2 ≥15 mmHg (≥20 mmHg si edad >64 años) en gasometría arterial en aire ambiente, 3) evidencia de dilataciones vasculares intrapulmonares por ecocardiograma con contraste (burbujas) positivo o gammagrafía con macroagregados de albúmina marcados.","laboratorio":"Gasometría arterial en posición sentada/de pie en aire ambiente (mejor sensibilidad que en decúbito).","imagen":"Ecocardiograma transtorácico con contraste salino agitado (\"bubble study\"): aparición tardía (>3-6 ciclos cardiacos) de burbujas en cavidades izquierdas confirma shunt intrapulmonar (vs. inmediato en shunt intracardiaco); gammagrafía pulmonar de perfusión con macroagregados de albúmina Tc-99m cuantifica el grado de shunt.","complementarios":"Pruebas de función pulmonar para descartar enfermedad pulmonar concomitante que explique la hipoxemia.","dx_diferencial":"EPOC, enfermedad pulmonar intersticial, TEP crónico, cardiopatía cianógena, hidrotórax hepático masivo.","tx_medico":"Oxígeno suplementario si PaO2 <60 mmHg; evitar tabaquismo.","tx_farmacologico":"No existe tratamiento farmacológico eficaz demostrado que revierta el SHP de forma sostenida; múltiples agentes (pentoxifilina, análogos de somatostatina, azul de metileno) han sido estudiados sin beneficio consistente.","tx_intervencionista":"Embolización de dilataciones vasculares focales grandes tipo \"arteriovenosas\" en casos seleccionados no candidatos a trasplante inmediato.","criterios_uci":"Hipoxemia severa refractaria, especialmente en el perioperatorio de trasplante.","criterios_tips":"No indicado para tratar SHP (puede incluso empeorarlo).","criterios_trasplante":"El trasplante hepático es el único tratamiento definitivo (resolución en la mayoría de los casos en 6-12 meses); PaO2 <60 mmHg otorga puntos de excepción MELD en muchos sistemas de asignación por el exceso de mortalidad en lista de espera.","seguimiento_hospitalario":"Oximetría continua, gasometrías seriadas si hipoxemia significativa.","seguimiento_ambulatorio":"Gasometría arterial periódica para monitorizar progresión; evaluación temprana para trasplante ante PaO2 <60 mmHg.","pronostico":"Sin trasplante, la supervivencia se reduce significativamente comparado con cirróticos sin SHP de similar función hepática; mortalidad relacionada con hipoxemia progresiva.","algoritmo":["Disnea/platipnea-ortodeoxia en cirrótico → gasometría arterial en aire ambiente sentado","Gradiente A-a ≥15 mmHg (≥20 si >64 años) → ecocardiograma con contraste salino","Contraste tardío positivo → confirma SHP → clasificar severidad por PaO2","PaO2 <60 mmHg → oxígeno suplementario + referencia prioritaria a trasplante hepático","Descartar enfermedad pulmonar concomitante con pruebas de función pulmonar"]},{"nombre":"Hipertensión Portopulmonar (HPoP)","color":"#35685f","definicion":"Desarrollo de hipertensión arterial pulmonar (grupo 1 de la clasificación de Dana Point) en el contexto de hipertensión portal, por remodelación vascular pulmonar obstructiva (vasoconstricción, proliferación de la íntima, hipertrofia de la media), fisiopatológicamente distinta y opuesta al SHP (vasodilatación).","fisiopatologia":"Exceso de mediadores vasoconstrictores/proliferativos (endotelina-1) y déficit relativo de vasodilatadores a nivel de la circulación pulmonar, sumado a microembolismo desde la circulación esplácnica congestionada, genera remodelación obstructiva progresiva de arterias pulmonares pequeñas con aumento de la resistencia vascular pulmonar.","epidemiologia":"Presente en 5-6% de los candidatos a trasplante hepático evaluados con cateterismo cardiaco derecho.","factores_riesgo":["Sexo femenino","Hepatitis autoinmune","Mayor duración de la hipertensión portal"],"clinica":"Disnea de esfuerzo progresiva, síncope, dolor torácico, signos de insuficiencia cardiaca derecha en fases avanzadas (edema, ingurgitación yugular).","criterios_dx":"Cateterismo cardiaco derecho confirmatorio: presión arterial pulmonar media (PAPm) >20 mmHg en reposo, resistencia vascular pulmonar >2-3 unidades Wood, presión de enclavamiento capilar pulmonar normal (<15 mmHg, para excluir causa poscapilar/cardiaca izquierda), en presencia de hipertensión portal.","laboratorio":"BNP/NT-proBNP como marcador de sobrecarga ventricular derecha (cribado, no diagnóstico).","imagen":"Ecocardiograma transtorácico como cribado inicial (presión sistólica de arteria pulmonar estimada >50 mmHg indica necesidad de cateterismo confirmatorio); debe realizarse en todo candidato a trasplante hepático.","complementarios":"Prueba de caminata de 6 minutos para clasificación funcional y seguimiento.","dx_diferencial":"Hipertensión pulmonar secundaria a cardiopatía izquierda (grupo 2), enfermedad pulmonar hipóxica crónica (grupo 3), tromboembolismo crónico (grupo 4), SHP (fisiopatología opuesta).","tx_medico":"Optimización de volumen (diuréticos) si hay signos de sobrecarga derecha; evitar betabloqueadores no selectivos en HPoP moderada-severa (pueden empeorar la hemodinamia pulmonar y reducir la capacidad de ejercicio) — diferencia clave de manejo respecto al resto de la hipertensión portal.","tx_farmacologico":"Terapias específicas para hipertensión arterial pulmonar: análogos de prostaciclina, antagonistas de receptores de endotelina (ambrisentán, macitentán), inhibidores de fosfodiesterasa-5 (sildenafil) o estimuladores de guanilato ciclasa soluble, seleccionados según severidad y en centros especializados, con el objetivo de optimizar la hemodinamia previo a trasplante.","tx_intervencionista":"No hay intervención mecánica específica; el manejo es farmacológico dirigido y, en casos severos refractarios, se contraindica el trasplante.","criterios_uci":"Descompensación de insuficiencia cardiaca derecha, perioperatorio de trasplante por alto riesgo de mortalidad intraoperatoria.","criterios_tips":"TIPS contraindicado en HPoP moderada-severa por riesgo de sobrecarga aguda del ventrículo derecho.","criterios_trasplante":"PAPm <35 mmHg (idealmente <25 mmHg o RVP normalizada con tratamiento) permite proceder a trasplante con riesgo aceptable; PAPm ≥45 mmHg o RVP muy elevada a pesar de tratamiento óptimo es contraindicación absoluta por mortalidad perioperatoria prohibitiva.","seguimiento_hospitalario":"Monitorización hemodinámica estrecha en el perioperatorio de trasplante si HPoP conocida.","seguimiento_ambulatorio":"Ecocardiograma y eventual cateterismo de control periódico; seguimiento conjunto con cardiología/neumología especializada en hipertensión pulmonar.","pronostico":"Sin tratamiento, la HPoP moderada-severa no tratada tiene mortalidad elevada; el tratamiento dirigido puede permitir reducir el riesgo lo suficiente para habilitar el trasplante en algunos pacientes.","algoritmo":["Todo candidato a trasplante hepático → ecocardiograma de cribado","PSAP estimada >50 mmHg → cateterismo cardiaco derecho confirmatorio","PAPm >20 mmHg + RVP elevada + presión de enclavamiento normal → confirma HPoP","Iniciar terapia específica dirigida (prostaciclinas/antagonistas de endotelina/iPDE5)","Reevaluación hemodinámica periódica: mejoría a PAPm <35 mmHg → habilita trasplante","Sin respuesta y PAPm ≥45 mmHg → contraindicación de trasplante"]},{"nombre":"Trombosis de la Vena Porta (TVP)","color":"#34547a","definicion":"Oclusión parcial o completa, aguda o crónica, del flujo sanguíneo en el sistema venoso portal (tronco principal y/o ramas intrahepáticas), frecuente en la cirrosis avanzada.","fisiopatologia":"Convergencia de la tríada de Virchow: enlentecimiento del flujo portal (hepatófugo o muy lento por la HTP), estado protrombótico relativo (a pesar de la coagulopatía global, existe un rebalance hemostático con niveles bajos de proteína C/S y antitrombina que puede favorecer trombosis) y disfunción/daño endotelial local.","epidemiologia":"Prevalencia 10-25% en cirróticos, aumentando con la severidad de la enfermedad hepática; mayor incidencia en espera de trasplante.","factores_riesgo":["Severidad de cirrosis/Child-Pugh avanzado","Enlentecimiento del flujo portal en Doppler","Trombofilias hereditarias/adquiridas concomitantes","Antecedente de TIPS disfuncional","Carcinoma hepatocelular (invasión tumoral vascular, distinguir de trombo bland)"],"clinica":"Frecuentemente asintomática y hallazgo incidental en imagen de vigilancia; en trombosis aguda extensa puede causar dolor abdominal, íleo, o empeoramiento agudo de la hipertensión portal (nuevo sangrado variceal, ascitis de novo); la trombosis mesentérica extensa puede causar isquemia intestinal.","criterios_dx":"Confirmación por Doppler (ausencia de flujo o flujo mínimo en la vena porta), con caracterización mediante TC o RM con contraste para definir extensión, cronicidad (cavernoma portal en crónica) y diferenciar trombo blando de invasión tumoral (realce arterial dentro del trombo sugiere HCC).","laboratorio":"No hay marcador específico; considerar estudio de trombofilia si hay factores atípicos (edad joven, sin cirrosis avanzada, trombosis extensa recurrente).","imagen":"Ultrasonido Doppler como cribado; TC/RM trifásica para caracterización completa, extensión (clasificación de Yerdel) y diferenciación de HCC con invasión vascular.","complementarios":"Alfafetoproteína si se sospecha componente tumoral.","dx_diferencial":"Invasión vascular por carcinoma hepatocelular (trombo tumoral), pileflebitis séptica (secundaria a proceso infeccioso intraabdominal).","tx_medico":"Vigilancia expectante en trombosis crónicas estables, no oclusivas, sin progresión ni impacto clínico, especialmente si no candidato a trasplante.","tx_farmacologico":"Anticoagulación (heparina de bajo peso molecular inicialmente, transición a anticoagulantes orales según el caso) indicada en trombosis aguda sintomática, trombosis con extensión mesentérica (riesgo de isquemia), o en candidatos activos a trasplante hepático para preservar la anastomosis quirúrgica; se debe individualizar el riesgo de sangrado variceal (optimizar profilaxis con BBNS/LEB antes de anticoagular si hay varices de alto riesgo).","tx_intervencionista":"TIPS en casos seleccionados para restaurar el flujo portal y facilitar la recanalización, particularmente en candidatos a trasplante con trombosis extensa; trombolisis dirigida por catéter en casos agudos extensos con isquemia mesentérica inminente (centros especializados).","criterios_uci":"Isquemia mesentérica aguda asociada (abdomen agudo).","criterios_tips":"Trombosis portal que compromete la viabilidad de un futuro trasplante o que causa descompensación aguda de la hipertensión portal refractaria a manejo médico.","criterios_trasplante":"La TVP no oclusiva no contraindica el trasplante; la trombosis extensa con compromiso mesentérico (Yerdel IV) puede requerir técnicas quirúrgicas complejas o trasplante multivisceral, y debe evaluarse tempranamente en centro especializado.","seguimiento_hospitalario":"Vigilancia de dolor abdominal, signos de isquemia intestinal, respuesta a anticoagulación si iniciada.","seguimiento_ambulatorio":"Doppler/TC de control a los 3-6 meses de anticoagulación para evaluar recanalización; duración de anticoagulación individualizada.","pronostico":"La trombosis no oclusiva frecuentemente se recanaliza espontáneamente o con anticoagulación; la extensión mesentérica y la trombosis crónica cavernomatosa tienen peor pronóstico funcional y quirúrgico.","algoritmo":["Hallazgo de TVP en Doppler de vigilancia o por síntomas agudos → TC/RM trifásica para caracterizar","Descartar componente tumoral (HCC con invasión vascular) con AFP e imagen dinámica","Trombosis aguda sintomática o extensión mesentérica → anticoagulación (tras optimizar profilaxis de varices)","Trombosis crónica estable no oclusiva sin síntomas → vigilancia por imagen","Candidato a trasplante con trombosis extensa → evaluación en centro especializado ± TIPS"]},{"nombre":"Coagulopatía Asociada a Cirrosis","color":"#8c3450","definicion":"Alteración compleja y bidireccional de la hemostasia en el cirrótico, caracterizada por un \"rebalance hemostático\" en el que descienden en paralelo tanto factores procoagulantes como anticoagulantes naturales, resultando en un sistema frágil y no simplemente \"hipocoagulable\".","fisiopatologia":"Disminución de síntesis hepática de factores procoagulantes (II, V, VII, IX, X, XI) pero también de anticoagulantes naturales (proteína C, proteína S, antitrombina); aumento compensador del factor VIII y del factor de von Willebrand (de origen endotelial); trombocitopenia por hiperesplenismo y menor trombopoyetina, parcialmente compensada por mayor función plaquetaria relativa; hiperfibrinólisis en descompensación aguda/sepsis.","epidemiologia":"El INR/TP prolongado está presente en la mayoría de los cirróticos descompensados pero NO predice de forma fiable el riesgo de sangrado ni protege de trombosis (los cirróticos tienen igual o mayor riesgo trombótico que la población general, incluyendo TVP).","factores_riesgo":["Severidad de la disfunción hepática","Trombocitopenia severa concomitante","Insuficiencia renal (disfunción plaquetaria urémica añadida)","Sepsis/CID sobreañadida"],"clinica":"Puede manifestarse como sangrado espontáneo (raro en ausencia de lesión estructural como varices) o, paradójicamente, eventos trombóticos (TVP, tromboembolismo venoso sistémico).","criterios_dx":"No existe un único test que capture el estado hemostático global; INR/TP y plaquetas reflejan solo parcialmente el riesgo real; pruebas viscoelásticas (tromboelastografía/TEG, ROTEM) ofrecen una evaluación más integral de la hemostasia global.","laboratorio":"INR, TP, TTP, fibrinógeno, plaquetas; los tres primeros están alterados de forma basal y crónica, por lo que su corrección \"a la normalidad\" antes de procedimientos no está respaldada por evidencia y puede ser perjudicial (sobrecarga de volumen, sin reducir sangrado real).","imagen":"No aplica de forma directa; imagen dirigida si se sospecha sangrado activo o trombosis.","complementarios":"Tromboelastografía/ROTEM para guiar transfusión en sangrado activo o previo a procedimientos de alto riesgo, reduce el uso innecesario de hemoderivados comparado con guiarse solo por INR.","dx_diferencial":"Coagulación intravascular diseminada (CID) verdadera en sepsis severa, déficit de vitamina K por colestasis/malnutrición (responde a reposición, a diferencia de la insuficiencia hepática), trombocitopenia inmune concomitante.","tx_medico":"No corregir INR de forma rutinaria antes de procedimientos de bajo riesgo (paracentesis, toracocentesis); evaluar riesgo-beneficio individualizado en procedimientos de alto riesgo.","tx_farmacologico":"Vitamina K parenteral si se sospecha componente colestásico/nutricional; ácido tranexámico en sangrado mucocutáneo con componente hiperfibrinolítico bajo supervisión especializada; agonistas del receptor de trombopoyetina (avatrombopag, lusutrombopag) previo a procedimientos electivos en trombocitopenia severa (<50,000/μL) para evitar transfusión plaquetaria.","tx_intervencionista":"Transfusión de plasma fresco congelado o plaquetas reservada para sangrado activo significativo o procedimientos de muy alto riesgo, guiada idealmente por pruebas viscoelásticas más que por INR/plaquetas aislados.","criterios_uci":"Sangrado activo no controlado con coagulopatía severa, CID verdadera asociada a sepsis.","criterios_tips":"No aplica directamente.","criterios_trasplante":"La coagulopatía severa refleja disfunción hepática avanzada y contribuye al MELD (vía INR), impactando la priorización para trasplante.","seguimiento_hospitalario":"Vigilancia de sangrado clínico más que corrección numérica aislada del INR; plaquetas y fibrinógeno antes de procedimientos invasivos mayores.","seguimiento_ambulatorio":"No requiere seguimiento específico aislado; se integra en la vigilancia global de la hepatopatía.","pronostico":"El riesgo trombótico y hemorrágico coexisten; la anticoagulación no está contraindicada de forma categórica por INR elevado cuando existe indicación clara (p.ej. TVP, fibrilación auricular).","algoritmo":["Cirrótico con INR prolongado + trombocitopenia sin sangrado activo → NO corregir de rutina","Procedimiento de bajo riesgo (paracentesis) → proceder sin profilaxis transfusional rutinaria","Procedimiento de alto riesgo o sangrado activo → evaluar con TEG/ROTEM si disponible","Trombocitopenia severa <50,000 previo a procedimiento electivo → considerar agonista de trombopoyetina o transfusión dirigida","Sospecha de indicación trombótica (TVP, FA) → no negar anticoagulación solo por INR elevado; individualizar"]},{"nombre":"Inmunodeficiencia e Infecciones Bacterianas en el Cirrótico","color":"#634a80","definicion":"Estado de disfunción inmune asociada a cirrosis (CAID, \"cirrhosis-associated immune dysfunction\"), que combina inmunodeficiencia funcional (mayor susceptibilidad a infecciones) e inflamación sistémica crónica de bajo grado, predisponiendo a infecciones bacterianas frecuentes y graves.","fisiopatologia":"Disfunción de células de Kupffer, menor producción de proteínas del complemento y opsoninas, alteración de la función de neutrófilos y células NK, disbiosis intestinal y aumento de la permeabilidad intestinal que favorece translocación bacteriana continua desde la luz intestinal, manteniendo un estado proinflamatorio sistémico que paradójicamente coexiste con inmunoparálisis funcional frente a nuevos patógenos.","epidemiologia":"Las infecciones bacterianas complican 25-35% de las hospitalizaciones por cirrosis descompensada y son el principal precipitante identificable de ACLF; mortalidad asociada 2-4 veces mayor que en no cirróticos con infección equivalente.","factores_riesgo":["Child-Pugh C/MELD elevado","Ascitis con proteínas bajas","Hemorragia digestiva reciente","Hospitalización/procedimientos invasivos recientes","Uso previo de antibióticos (resistencia)"],"clinica":"Los focos más frecuentes son PBE, infección del tracto urinario, neumonía, bacteriemia espontánea y celulitis/erisipela; la presentación puede ser atípica (sin fiebre franca) y manifestarse solo como deterioro de la función hepática, encefalopatía o disfunción renal.","criterios_dx":"Alta sospecha clínica ante cualquier deterioro agudo; cultivos dirigidos según foco (líquido ascítico, urocultivo, hemocultivos, radiografía de tórax).","laboratorio":"Biometría hemática, PCR/procalcitonina (interpretar con cautela, pueden estar falsamente elevadas o poco sensibles en cirrosis avanzada), lactato, paracentesis diagnóstica sistemática en todo ingreso con ascitis.","imagen":"Radiografía/TC de tórax si sospecha de foco pulmonar; ultrasonido/TC abdominal si sospecha de foco intraabdominal distinto de PBE.","complementarios":"Panel de cultivos según protocolo local de sepsis; vigilancia de gérmenes multirresistentes en pacientes con hospitalizaciones recientes o uso previo de antibióticos de amplio espectro.","dx_diferencial":"Descompensación no infecciosa de la cirrosis (debe descartarse activamente infección en TODO paciente con descompensación aguda, ya que su prevalencia es alta incluso sin fiebre).","tx_medico":"Búsqueda activa y sistemática de foco infeccioso ante cualquier descompensación aguda; medidas de soporte según severidad.","tx_farmacologico":"Antibioticoterapia empírica precoz guiada por foco sospechado y epidemiología local/nosocomial (considerar cobertura ampliada si hospitalización reciente o exposición previa a antibióticos); ajuste según cultivos; albúmina IV coadyuvante en infecciones con disfunción circulatoria significativa (más allá de la PBE, evidencia en estudio para otras infecciones graves).","tx_intervencionista":"Drenaje de foco cuando aplique (absceso, colección).","criterios_uci":"Sepsis/choque séptico, ACLF con falla de ≥2 órganos, necesidad de soporte vasopresor o ventilatorio.","criterios_tips":"No aplica en el manejo agudo de la infección.","criterios_trasplante":"Una infección grave resuelta con descompensación asociada debe motivar referencia a evaluación de trasplante; infección activa no controlada es contraindicación temporal para trasplante electivo.","seguimiento_hospitalario":"Reevaluación clínica a las 48-72h de iniciado el antibiótico, de-escalamiento según cultivos, vigilancia de nueva disfunción orgánica (score CLIF-OF).","seguimiento_ambulatorio":"Vacunación (influenza anual, neumococo, hepatitis A/B si no inmune, COVID-19 según esquema vigente); profilaxis antibiótica secundaria si PBE previa.","pronostico":"La infección bacteriana es el principal desencadenante de ACLF y se asocia a mortalidad significativamente mayor comparado con descompensación no infecciosa.","algoritmo":["Descompensación aguda de cirrosis (cualquier tipo) → buscar activamente infección incluso sin fiebre","Paracentesis, urocultivo, hemocultivos, radiografía de tórax según sospecha clínica","Iniciar antibiótico empírico precoz si alta sospecha, sin esperar confirmación microbiológica","Reevaluar a 48-72h: respuesta clínica y resultados de cultivos → de-escalar o ajustar","Deterioro multiorgánico asociado → manejo en UCI, evaluar criterios de ACLF"]},{"nombre":"Desnutrición y Sarcopenia","color":"#a3702a","definicion":"Depleción del estado nutricional global (desnutrición) y, específicamente, pérdida de masa y función del músculo esquelético (sarcopenia), complicaciones altamente prevalentes e infradiagnosticadas de la cirrosis, con impacto pronóstico independiente.","fisiopatologia":"Ingesta oral reducida (anorexia, saciedad precoz por ascitis, restricciones dietéticas mal indicadas), malabsorción (colestasis, sobrecrecimiento bacteriano), estado catabólico/hipermetabólico crónico con periodos de ayuno funcionalmente prolongados (depleción de glucógeno hepático que obliga a gluconeogénesis a partir de proteína muscular incluso en ayunos cortos), hiperamonemia crónica que estimula miostatina y autofagia muscular, y menor síntesis proteica hepática.","epidemiologia":"Desnutrición proteico-calórica presente en 20-50% de cirróticos compensados y hasta 80% en descompensados; sarcopenia presente en 30-70% según método diagnóstico y población.","factores_riesgo":["Cirrosis descompensada/Child-Pugh avanzado","Ascitis (enmascara la pérdida de peso real)","Restricciones dietéticas excesivas mal indicadas","Etiología alcohólica","Sexo masculino para sarcopenia"],"clinica":"Pérdida de masa muscular temporal y de extremidades (frecuentemente enmascarada por ascitis/edema en el peso corporal total), debilidad, fatiga, fragilidad, caídas.","criterios_dx":"Herramientas de cribado (Royal Free Hospital Global Assessment, MUST); sarcopenia definida por índice de músculo esquelético en L3 por TC (umbrales específicos por sexo) o dinamometría de fuerza de prensión manual reducida.","laboratorio":"Albúmina (limitada como marcador nutricional aislado por su síntesis hepática alterada independientemente del estado nutricional); prealbúmina de utilidad limitada similar.","imagen":"TC abdominal (secuencia ya realizada frecuentemente por otras indicaciones) para medición del índice de músculo psoas/esquelético en L3, método más objetivo disponible.","complementarios":"Evaluación por nutrición clínica especializada; bioimpedancia si disponible (limitada por sobrecarga de líquidos).","dx_diferencial":"Caquexia de otras causas (neoplasia concomitante), miopatías primarias, hipotiroidismo.","tx_medico":"Evitar ayunos prolongados: fraccionar la ingesta en 4-6 comidas/día incluyendo una colación nocturna tardía rica en carbohidratos complejos (reduce el catabolismo proteico del ayuno nocturno prolongado); NO restringir proteínas de forma rutinaria (mito histórico) salvo encefalopatía refractaria aguda transitoria.","tx_farmacologico":"Suplementación con aminoácidos de cadena ramificada (BCAA) en casos seleccionados con intolerancia proteica o EH recurrente, para alcanzar metas proteicas sin precipitar EH; vitaminas liposolubles (A, D, E, K) y complejo B si colestasis o etiología alcohólica.","tx_intervencionista":"Sonda nasoenteral/nutrición enteral si ingesta oral insuficiente pese a optimización; nutrición parenteral solo si tracto gastrointestinal no funcional.","criterios_uci":"No aplica de forma directa, salvo desnutrición severa que complica el manejo de otras condiciones críticas.","criterios_tips":"No aplica.","criterios_trasplante":"La sarcopenia severa es un predictor independiente de mortalidad en lista de espera y de peores desenlaces post-trasplante; debe evaluarse activamente en toda evaluación de trasplante y optimizarse antes/durante la espera.","seguimiento_hospitalario":"Interconsulta a nutrición clínica desde el ingreso en todo paciente descompensado; monitorización de ingesta calórico-proteica real.","seguimiento_ambulatorio":"Metas nutricionales: 35 kcal/kg/día y 1.2-1.5 g/kg/día de proteína en cirrosis descompensada (mayor que la población general); programa de ejercicio de resistencia progresiva para contrarrestar sarcopenia; reevaluación periódica del estado nutricional.","pronostico":"La sarcopenia se asocia de forma independiente a mayor mortalidad, más complicaciones (incluida EH) y peor calidad de vida, independientemente del MELD.","algoritmo":["Todo cirrótico → cribado nutricional al diagnóstico y en cada descompensación","Sospecha de desnutrición/sarcopenia → evaluación formal (TC en L3 si disponible, dinamometría)","Establecer plan: 35 kcal/kg/día, 1.2-1.5 g/kg/día proteína, fraccionamiento en 4-6 tomas + colación nocturna","Intolerancia proteica/EH recurrente → BCAA como fuente proteica alternativa","Ingesta oral insuficiente pese a optimización → nutrición enteral","Referencia a programa de ejercicio y reevaluación periódica"]},{"nombre":"Osteodistrofia Hepática","color":"#5c7a3a","definicion":"Alteración del metabolismo óseo asociada a hepatopatía crónica, que incluye osteopenia y osteoporosis (predominante) y, con menor frecuencia, osteomalacia, con mayor riesgo de fracturas.","fisiopatologia":"Menor absorción intestinal de vitamina D y calcio (especialmente en colestasis crónica), menor hidroxilación hepática de vitamina D, hipogonadismo asociado, inmovilidad relativa, desnutrición proteico-calórica, y en algunos casos efecto directo de la retención de bilirrubina/ácidos biliares sobre los osteoblastos; el alcohol tiene efecto tóxico directo adicional sobre el hueso.","epidemiologia":"Osteoporosis presente en 20-50% de cirróticos, con mayor prevalencia en colestasis crónica (CBP, CEP) y etiología alcohólica; riesgo de fractura 2-3 veces mayor que la población general.","factores_riesgo":["Colestasis crónica (CBP/CEP)","Etiología alcohólica","Uso de corticoides","Sexo femenino postmenopáusico","Sarcopenia/desnutrición concomitante","Inmovilidad"],"clinica":"Habitualmente asintomática hasta la fractura (vertebral por fragilidad o de cadera); dolor óseo si osteomalacia.","criterios_dx":"Densitometría ósea (DEXA) con criterios OMS estándar: T-score ≤-2.5 osteoporosis, entre -1 y -2.5 osteopenia.","laboratorio":"Calcio, fósforo, 25-hidroxivitamina D, paratohormona (PTH); fosfatasa alcalina ósea si se sospecha osteomalacia (aunque limitada por elevación hepática concomitante).","imagen":"DEXA como estudio de elección; radiografías dirigidas si sospecha de fractura vertebral.","complementarios":"Evaluación de factores de riesgo adicionales (FRAX) para decisión de tratamiento.","dx_diferencial":"Osteoporosis primaria (postmenopáusica/senil) no relacionada con hepatopatía, hiperparatiroidismo, mieloma múltiple si hallazgos atípicos.","tx_medico":"Optimización de actividad física con ejercicio de carga, cesación de alcohol y tabaco.","tx_farmacologico":"Suplementación con calcio (1000-1200 mg/día) y vitamina D (800-1000 UI/día, ajustar según niveles séricos); bifosfonatos en osteoporosis confirmada (considerar vía oral vs. IV según tolerancia y varices esofágicas si hay riesgo de esofagitis).","tx_intervencionista":"No aplica.","criterios_uci":"No aplica.","criterios_tips":"No aplica.","criterios_trasplante":"La osteoporosis severa no contraindica el trasplante pero debe optimizarse previamente, ya que el riesgo de fractura aumenta en el primer año post-trasplante por el uso de corticoides/inmunosupresores.","seguimiento_hospitalario":"No aplica como manejo agudo específico.","seguimiento_ambulatorio":"DEXA de cribado al diagnóstico de cirrosis (especialmente colestásica) y cada 1-2 años según hallazgos; reevaluación periódica post-trasplante.","pronostico":"El riesgo de fractura aumenta la morbimortalidad, especialmente en el periodo peritrasplante.","algoritmo":["Cirrosis diagnosticada (especialmente colestásica o alcohólica) → DEXA de cribado","T-score normal → repetir en 2 años","Osteopenia → optimizar calcio/vitamina D + reevaluar en 1-2 años","Osteoporosis → calcio + vitamina D + bifosfonato + reevaluación periódica","Candidato a trasplante → optimización previa por mayor riesgo de fractura postoperatorio"]},{"nombre":"Alteraciones Endocrinas y Metabólicas","color":"#46617a","definicion":"Conjunto de disfunciones hormonales y metabólicas secundarias a la insuficiencia hepatocelular y la hipertensión portal, incluyendo hipogonadismo, alteraciones tiroideas, disglucemia (\"diabetes hepatógena\") e insuficiencia suprarrenal relativa.","fisiopatologia":"Menor clearance hepático de estrógenos y aromatización periférica aumentada de andrógenos generan hiperestrogenismo relativo (arañas vasculares, ginecomastia, atrofia testicular); resistencia a la insulina por disfunción hepática y derivación portosistémica altera el metabolismo de la glucosa (\"diabetes hepatógena\"); la insuficiencia suprarrenal relativa (\"insuficiencia suprarrenal relacionada con enfermedad crítica\") se relaciona con menor síntesis de colesterol/precursores esteroideos y disfunción del eje hipotálamo-hipófisis-suprarrenal en el paciente crítico cirrótico.","epidemiologia":"Diabetes/intolerancia a la glucosa presente hasta en 30-40% de cirróticos; insuficiencia suprarrenal relativa descrita en 30-60% de cirróticos críticamente enfermos (sepsis/choque).","factores_riesgo":["MASLD/MASH como etiología de base (bidireccional con diabetes)","Cirrosis avanzada/Child-Pugh C","Sepsis/choque séptico para insuficiencia suprarrenal relativa"],"clinica":"Hipogonadismo (disminución de libido, atrofia testicular, irregularidades menstruales), síntomas de disglucemia, hipotensión refractaria a volumen/vasopresores sugestiva de insuficiencia suprarrenal en el paciente crítico.","criterios_dx":"Diabetes hepatógena por criterios estándar de glucemia/HbA1c (con la limitación de que la HbA1c puede estar falsamente disminuida por menor vida media eritrocitaria/anemia); insuficiencia suprarrenal relativa sugerida por cortisol basal bajo o respuesta inadecuada a prueba de estimulación con ACTH en el contexto crítico.","laboratorio":"Glucosa en ayuno, HbA1c (interpretar con cautela), perfil tiroideo (TSH, T4 libre), testosterona/estradiol si clínica sugestiva, cortisol basal/post-ACTH en paciente crítico con inestabilidad hemodinámica refractaria.","imagen":"No aplica de forma directa.","complementarios":"Ninguno adicional específico.","dx_diferencial":"Diabetes mellitus tipo 2 primaria no relacionada con hepatopatía, hipogonadismo de otra causa, insuficiencia suprarrenal primaria verdadera (enfermedad de Addison).","tx_medico":"Manejo de estilo de vida y control metabólico general; evitar hipoglucemiantes con riesgo elevado de hipoglucemia (sulfonilureas) en Child-Pugh avanzado.","tx_farmacologico":"Metformina puede continuarse con precaución en cirrosis compensada (contraindicada en descompensación avanzada por riesgo de acidosis láctica); insulina de elección en descompensación avanzada; hidrocortisona en insuficiencia suprarrenal relativa documentada con choque refractario a vasopresores.","tx_intervencionista":"No aplica.","criterios_uci":"Choque refractario a vasopresores con sospecha de insuficiencia suprarrenal relativa (indicación de prueba/tratamiento empírico con hidrocortisona en ese contexto).","criterios_tips":"No aplica.","criterios_trasplante":"No es indicación aislada; se optimiza el control metabólico perioperatorio.","seguimiento_hospitalario":"Control glucémico con esquema de insulina en el paciente hospitalizado; sospecha activa de insuficiencia suprarrenal en choque refractario.","seguimiento_ambulatorio":"Control periódico de glucemia/HbA1c interpretada con cautela, perfil tiroideo anual en etiologías autoinmunes.","pronostico":"La diabetes hepatógena se asocia a mayor riesgo de descompensación y peor pronóstico global; la insuficiencia suprarrenal relativa no tratada empeora el pronóstico en el paciente crítico.","algoritmo":["Cirrótico con disglucemia → confirmar diagnóstico con glucemia/HbA1c (cautela interpretativa)","Iniciar manejo con insulina si descompensación avanzada; metformina solo si compensado","Paciente crítico con choque refractario a vasopresores → sospechar insuficiencia suprarrenal relativa","Cortisol basal bajo o prueba ACTH inadecuada → iniciar hidrocortisona empírica"]},{"nombre":"Carcinoma Hepatocelular (HCC)","color":"#7a3030","definicion":"Neoplasia maligna primaria del hepatocito, la complicación oncológica más frecuente y temida de la cirrosis, que se desarrolla predominantemente sobre un hígado cirrótico (>90% de los casos).","fisiopatologia":"Secuencia de daño-regeneración-mutación: la inflamación y regeneración hepatocitaria crónica en el contexto de fibrosis aumenta la tasa de mutaciones somáticas; nódulos displásicos de bajo y alto grado representan lesiones premalignas que progresan a HCC franco mediante acumulación de alteraciones genéticas (activación de vías Wnt/β-catenina, TERT, TP53, entre otras) y neoangiogénesis progresiva característica (adquisición de suministro arterial puro, base del diagnóstico por imagen dinámica).","epidemiologia":"Incidencia anual en cirróticos vigilados 2-4% (mayor en VHB/VHC y hemocromatosis); es una de las principales causas de mortalidad en pacientes con cirrosis compensada.","factores_riesgo":["Cirrosis de cualquier etiología (principal factor)","Hepatitis B crónica incluso sin cirrosis franca en ciertos subgrupos","Edad avanzada, sexo masculino","Consumo de alcohol activo","Coinfección VHB/VHC","Aflatoxinas (contexto endémico)"],"clinica":"Frecuentemente asintomático en fase de detección por vigilancia; en fases avanzadas: dolor en hipocondrio derecho, pérdida de peso, descompensación aguda de la cirrosis previamente estable (ascitis de nuevo inicio, hemorragia por invasión/trombosis portal tumoral), masa palpable.","figura":"bclc-estadificacion","criterios_dx":"Sistema LI-RADS/criterios no invasivos AASLD: en nódulo ≥1 cm en hígado cirrótico con patrón dinámico típico (hipercaptación arterial + lavado (\"washout\") en fase venosa/tardía) en TC o RM trifásica/multifásica, el diagnóstico se establece SIN necesidad de biopsia (LR-5 = HCC definitivo). Biopsia reservada para patrones atípicos (LR-4/LR-M) o hígado no cirrótico.","laboratorio":"Alfafetoproteína (AFP): útil como coadyuvante de vigilancia y seguimiento, pero insuficiente como prueba diagnóstica aislada (sensibilidad limitada, puede ser normal en HCC bien diferenciado); no sustituye a la imagen dinámica.","imagen":"Ultrasonido hepático semestral como método de vigilancia (con o sin AFP concomitante); TC o RM trifásica/multifásica como confirmación diagnóstica ante hallazgo sospechoso, clasificando el nódulo según LI-RADS (LR-1 a LR-5, LR-M para probable no-HCC maligno).","complementarios":"Estadificación con sistema BCLC (Barcelona Clinic Liver Cancer), que integra estadio tumoral, función hepática (Child-Pugh) y estado funcional (ECOG), guiando directamente la elección terapéutica.","dx_diferencial":"Nódulo displásico de alto grado, colangiocarcinoma intrahepático, metástasis hepática, hemangioma atípico, hiperplasia nodular focal.","tx_medico":"Optimización de la función hepática de base y manejo de comorbilidades como parte de la evaluación de elegibilidad terapéutica.","tx_farmacologico":"Enfermedad avanzada (BCLC C): terapias sistémicas de primera línea combinando inmunoterapia (atezolizumab + bevacizumab, o durvalumab + tremelimumab) según función hepática y disponibilidad; inhibidores de tirosina-cinasa (sorafenib, lenvatinib) como alternativa o segunda línea.","tx_intervencionista":"Estadio muy temprano/temprano (BCLC 0-A): ablación percutánea (radiofrecuencia/microondas) para nódulos ≤3 cm, o resección quirúrgica en función hepática preservada sin hipertensión portal significativa. Estadio intermedio (BCLC B): quimioembolización transarterial (TACE) o radioembolización con Y-90 (TARE) como puente o tratamiento paliativo.","criterios_uci":"No aplica de forma directa salvo complicaciones agudas asociadas (sangrado tumoral, descompensación hepática severa post-tratamiento).","criterios_tips":"No indicado para el manejo del HCC en sí; puede coexistir con manejo de complicaciones de hipertensión portal asociadas.","criterios_trasplante":"Criterios de Milán (nódulo único ≤5 cm, o hasta 3 nódulos cada uno ≤3 cm, sin invasión vascular macroscópica ni enfermedad extrahepática) son el estándar para trasplante hepático con excelente supervivencia; criterios expandidos (UCSF y otros) permiten trasplante en casos seleccionados fuera de Milán con adecuada selección mediante respuesta a terapia de reducción (\"downstaging\").","seguimiento_hospitalario":"No aplica como manejo agudo específico salvo complicaciones post-procedimiento (síndrome post-embolización, descompensación hepática).","seguimiento_ambulatorio":"Vigilancia semestral con ultrasonido ± AFP en TODO cirrótico independientemente de la etiología (y en hepatitis B crónica de alto riesgo sin cirrosis); reevaluación por imagen dinámica tras cualquier tratamiento local-regional para evaluar respuesta (criterios mRECIST).","pronostico":"Determinado fundamentalmente por el estadio BCLC al diagnóstico; supervivencia a 5 años >70% en estadios muy tempranos tratados con resección/trasplante/ablación, vs. meses en enfermedad avanzada no tratada — de ahí la importancia crítica de la vigilancia semestral.","algoritmo":["Todo cirrótico → vigilancia con ultrasonido hepático ± AFP cada 6 meses","Nódulo <1 cm → repetir US en 3-4 meses","Nódulo ≥1 cm → TC/RM trifásica dinámica","Patrón típico (hipercaptación arterial + lavado) → LR-5, diagnóstico de HCC sin biopsia","Patrón atípico → LR-4/LR-M → biopsia o seguimiento estrecho","Estadificar con BCLC (tumor + función hepática + ECOG)","BCLC 0-A → resección/ablación/trasplante (criterios de Milán)","BCLC B → TACE/TARE","BCLC C → terapia sistémica (inmunoterapia ± antiangiogénico)","BCLC D → manejo paliativo/soporte"]},{"nombre":"Falla Hepática Aguda sobre Crónica (ACLF)","color":"#6b2828","definicion":"Síndrome caracterizado por descompensación aguda de la cirrosis asociada a falla de uno o más órganos extrahepáticos y alta mortalidad a corto plazo (28-90 días), habitualmente precipitado por un evento identificable (infección, hemorragia, hepatitis alcohólica aguda) sobre una hepatopatía crónica previamente compensada o descompensada estable.","fisiopatologia":"Respuesta inflamatoria sistémica exagerada y desregulada (\"tormenta de citocinas\") desencadenada por el factor precipitante, que sobrepasa la capacidad de reserva funcional hepática y sistémica, generando disfunción mitocondrial e inmunometabólica en múltiples órganos (hígado, riñón, cerebro, coagulación, circulación, pulmón) de forma simultánea, con un componente de inmunoparálisis secundaria que aumenta el riesgo de infecciones sobreañadidas.","epidemiologia":"Presente en 20-40% de las hospitalizaciones por descompensación aguda de cirrosis (cohorte CANONIC); mortalidad a 28 días proporcional al grado: ACLF-1 ~20%, ACLF-2 ~30-40%, ACLF-3 (≥3 fallas orgánicas) >70-80% sin trasplante.","factores_riesgo":["Infección bacteriana (precipitante más frecuente)","Hemorragia digestiva","Hepatitis alcohólica aguda grave sobreañadida","Suspensión abrupta de tratamiento antiviral en VHB","Cirugía mayor reciente","Hasta 40% sin precipitante identificable"],"clinica":"Deterioro clínico rápido y grave con combinación variable de ictericia progresiva, encefalopatía, oliguria/anuria, inestabilidad hemodinámica y/o insuficiencia respiratoria, superpuesto a los signos de la cirrosis de base.","figura":"clif-of-organos","criterios_dx":"Definición EASL-CLIF (consorcio CANONIC, refrendada por la guía EASL 2023): presencia de al menos una falla orgánica según el score CLIF-OF (6 sistemas: hígado -bilirrubina-, riñón -creatinina/diálisis-, cerebro -West Haven-, coagulación -INR-, circulación -PAM/vasopresores-, respiración -PaO2/FiO2 o SpO2/FiO2-) asociada a alta mortalidad a 28 días; se gradúa en ACLF-1 (una falla renal, o falla de otro órgano con creatinina/EH leve-moderada), ACLF-2 (dos fallas orgánicas), ACLF-3 (≥3 fallas orgánicas; la guía EASL 2023 subdivide en ACLF-1a/1b, y ACLF-3a con 3 fallas frente a ACLF-3b con ≥4 fallas — ver Figura 2). El CLIF-C ACLF predice mejor la mortalidad a 28 días que el MELD, MELD-Na o Child-Pugh (AUROC 0.79 vs. ~0.70, cohorte CANONIC). Algoritmo secuencial recomendado: calcular CLIF-C OF al ingreso de todo paciente con descompensación aguda → si cumple criterios de ACLF, usar CLIF-C ACLF; si no los cumple, usar CLIF-C AD para estratificar riesgo (≥60 puntos: alto riesgo, mortalidad a 3 meses >30%; 46-59: intermedio, 2-30%; <45: bajo, <2%).","laboratorio":"Panel completo diario: bilirrubina, creatinina, INR, gasometría arterial, lactato, biometría hemática, electrolitos — necesario para calcular el score CLIF-OF y CLIF-C ACLF de forma seriada.","imagen":"Dirigida a la búsqueda del precipitante (radiografía/TC de tórax, ultrasonido abdominal, paracentesis) y a la evaluación de complicaciones (edema cerebral en casos extremos, aunque raro comparado con falla hepática aguda fulminante).","complementarios":"Score CLIF-C ACLF calculado de forma seriada (días 3-7) como mejor predictor dinámico de mortalidad y herramienta para decisión de limitación del esfuerzo terapéutico o priorización de trasplante urgente.","dx_diferencial":"Descompensación aguda simple (sin falla orgánica extrahepática), falla hepática aguda sobre hígado previamente sano (fulminante, sin cirrosis de base), sepsis severa sin hepatopatía de base.","tx_medico":"Identificación y tratamiento agresivo e inmediato del factor precipitante (piedra angular del manejo); soporte multiorgánico según fallas presentes (ver complicaciones específicas: SHR, EH, coagulopatía); nutrición precoz.","tx_farmacologico":"Antibioticoterapia empírica de amplio espectro precoz si sospecha infecciosa (sin esperar confirmación); terlipresina/noradrenalina + albúmina si falla renal tipo HRS-AKI asociada; manejo específico de hepatitis alcohólica grave sobreañadida (corticoides con score de Lille de reevaluación a 7 días) si aplica.","tx_intervencionista":"Terapias de soporte orgánico extracorpóreo (terapia de reemplazo renal continua, y en centros seleccionados sistemas de soporte hepático artificial/MARS o plasmaféresis de alto volumen) como puente a recuperación o trasplante en casos seleccionados.","criterios_uci":"Indicaciones de UCI (guía EASL 2023): necesidad de soporte orgánico (vasopresores, ventilación mecánica o TRR), hemorragia masiva, encefalopatía grado III-IV (protección de vía aérea) o choque séptico — idealmente dentro de las primeras 6h del diagnóstico. Indicaciones de cuidados intermedios: hemorragia variceal, encefalopatía grado II-III, o sepsis con SHR-IRA o falla hepática/de coagulación. Contraindicaciones relativas a valorar caso por caso (salvo que el paciente esté en evaluación o lista de trasplante): comorbilidad de muy mal pronóstico, neoplasia avanzada (expectativa <6 meses), fragilidad grave por sarcopenia, Karnofsky ≤40, o enfermedad pulmonar/cardiaca/neurológica grave asociada a ACLF-3. El pronóstico debe reevaluarse a los 3-7 días de soporte orgánico pleno, no al ingreso; ≥4 fallas orgánicas o CLIF-C ACLF >70 puntos en ese momento, sin opción de trasplante, deben motivar reevaluar la adecuación de continuar el soporte.","criterios_tips":"El TIPS electivo está contraindicado en la fase aguda de ACLF por el riesgo de empeorar la falla hepática. Sin embargo, el TIPS preventivo o de rescate para hemorragia variceal sí mejora los desenlaces en ACLF-1 y ACLF-2 (consenso Baveno/EASL 2023), incluso con bilirrubina >5 mg/dL; no hay evidencia en ACLF-3. La encefalopatía hepática por sí sola no debe considerarse contraindicación absoluta para el TIPS.","criterios_trasplante":"El trasplante hepático urgente es el único tratamiento definitivo con beneficio de supervivencia demostrado en ACLF-2/3 seleccionados: el trasplante temprano (días 3-7) se asocia a supervivencia a 6 meses de ~81% frente a ~10% sin trasplante. La futilidad del trasplante en ACLF-3 debe decidirse caso por caso; un consenso de expertos (2021, referenciado en la guía EASL 2023) propuso —sin validación prospectiva completa aún— factores como fragilidad grave, sepsis no controlada (excepto infección urinaria), infección por bacterias panresistentes, PaO2/FiO2 <150, requerimiento de noradrenalina >1 mcg/kg/min, lactato >9 mmol/L o deterioro clínico progresivo. Debe considerarse el uso de injertos de criterios expandidos para reducir la mortalidad en lista de espera en pacientes con ACLF-3.","seguimiento_hospitalario":"Recalcular CLIF-C ACLF diariamente los primeros 3-7 días (la trayectoria, más que el valor aislado al ingreso, define el pronóstico y guía decisiones de intensidad de cuidados y trasplante urgente).","seguimiento_ambulatorio":"En sobrevivientes, seguimiento estrecho por alto riesgo de recurrencia y necesidad de rehabilitación multiorgánica (renal, nutricional, neurológica).","pronostico":"Mortalidad a 28 días fuertemente ligada al número de fallas orgánicas y su trayectoria en los primeros días; ACLF-3 con >70-80% de mortalidad sin trasplante hepático oportuno.","algoritmo":["Descompensación aguda de cirrosis con deterioro multiorgánico → calcular CLIF-OF/CLIF-C ACLF al ingreso","Identificar y tratar agresivamente el precipitante (antibióticos empíricos, control de sangrado, manejo de hepatitis alcohólica)","Clasificar grado ACLF (1/2/3) y decidir nivel de cuidados (UCI si ACLF-2/3)","Soporte específico por órgano (vasoconstrictor+albúmina si SHR, protección de vía aérea si EH severa, TRR si falla renal refractaria)","Recalcular CLIF-C ACLF a las 48-72h y día 7: trayectoria mejora → continuar soporte; trayectoria empeora → evaluación urgente de trasplante hepático","ACLF-3 persistente sin mejoría y sin opción de trasplante → discusión de limitación del esfuerzo terapéutico con equipo y familia"]}],"seguimiento_intrahospitalario":{"intro":"Todo paciente cirrótico hospitalizado, especialmente por descompensación aguda, requiere monitorización sistemática y estructurada para detectar precozmente nuevas complicaciones, guiar el ajuste terapéutico y definir criterios de escalamiento de cuidados.","parametros":["Signos vitales cada turno (o más frecuente según severidad): PA, FC, FR, SpO2, temperatura — la fiebre puede estar ausente incluso en infección grave, por lo que su ausencia no descarta sepsis.","Estado neurológico y grado de encefalopatía (escala de West Haven) al menos una vez por turno; documentar asterixis y orientación.","Balance hídrico estricto (ingresos/egresos) y diuresis horaria si inestabilidad o sospecha de disfunción renal.","Peso corporal diario a la misma hora (mejor marcador de respuesta a diuréticos que el balance hídrico calculado, más propenso a error).","Perímetro abdominal si ascitis significativa, como referencia complementaria.","Sodio, potasio y creatinina cada 24-72h durante titulación diurética o en descompensación aguda (más frecuente si cambios rápidos o uso de vasoconstrictores/diuréticos en dosis altas).","Biometría hemática seriada (vigilar trombocitopenia progresiva, leucocitosis sugestiva de infección, anemización).","Pruebas de función hepática (bilirrubina, transaminasas, fosfatasa alcalina) y albúmina cada 48-72h según contexto clínico.","INR seriado como parte del MELD y para vigilar tendencia de la función de síntesis.","Reevaluación de la necesidad de paracentesis diagnóstica repetida ante cualquier deterioro clínico inexplicado en paciente con ascitis (no limitarse a la evaluación inicial).","Cálculo diario de MELD-Na y, si aplica, CLIF-C ACLF en pacientes con descompensación multiorgánica, para objetivar trayectoria clínica."],"criterios_uci_general":"Inestabilidad hemodinámica, necesidad de vasopresores, protección de vía aérea (EH grado III-IV, hematemesis masiva), insuficiencia respiratoria, ACLF grado 2-3, necesidad de terapia de reemplazo renal urgente.","criterios_tips_general":"Ascitis refractaria en candidato elegible, hemorragia variceal de alto riesgo (TIPS precoz) o refractaria al tratamiento combinado, trombosis portal seleccionada en candidato a trasplante.","criterios_trasplante_general":"Toda primera descompensación (ascitis, hemorragia variceal, EH, ictericia), HRS-AKI sin respuesta a vasoconstrictores, HCC dentro o cerca de criterios de Milán, ACLF-2/3, SHP con PaO2 <60 mmHg — deben motivar referencia temprana, ya que la evaluación y el proceso de listado toman tiempo y la ventana de oportunidad puede ser estrecha.","prevencion":"Estrategias activas de prevención durante la hospitalización: profilaxis de PBE según criterios, evitar nefrotóxicos (AINEs, aminoglucósidos, contraste yodado sin hidratación adecuada), vigilancia de sobrediuresis, lactulosa profiláctica si hemorragia digestiva (reduce EH post-sangrado), tromboprofilaxis mecánica/farmacológica individualizada (los cirróticos NO están protegidos de tromboembolismo venoso por su coagulopatía basal), vacunación oportuna antes del alta si no se ha realizado."},"seguimiento_ambulatorio_general":{"intro":"El seguimiento ambulatorio estructurado del paciente cirrótico compensado y descompensado estable es esencial para detectar tempranamente la primera/nueva descompensación, realizar vigilancia oncológica y optimizar el estado general antes de una eventual necesidad de trasplante.","frecuencia_consultas":"Cirrosis compensada sin comorbilidad: cada 6 meses. Cirrosis descompensada o con comorbilidad activa: cada 1-3 meses o según necesidad clínica.","laboratorios_periodicos":"Biometría hemática, función hepática y renal, electrolitos, INR cada 3-6 meses según estabilidad; perfil etiológico específico según causa de base (carga viral en hepatitis B/C, ferritina en hemocromatosis tratada, etc.).","vigilancia_hcc":"Ultrasonido hepático semestral con o sin alfafetoproteína concomitante en TODO paciente cirrótico, independientemente de la etiología o del estado de compensación, mientras sea candidato a tratamiento en caso de detección.","vigilancia_endoscopica":"Según criterios de Baveno VII: diferir endoscopia si LSM <20 kPa y plaquetas >150,000 (bajo riesgo de varices grandes); si no cumple criterio, endoscopia de tamizaje con periodicidad según hallazgo (repetir cada 2-3 años si no hay varices y la enfermedad hepática es estable, cada 1 año si hay daño hepático continuo o progresión, según hallazgo de varices ver el apartado específico).","vacunacion":"Hepatitis A y B (si no inmune), influenza anual, neumococo (conjugada y polisacárida según esquema), COVID-19 según recomendaciones vigentes, herpes zóster en mayores de 50 años; evitar vacunas de virus vivos atenuados si hay descompensación severa o se anticipa inmunosupresión postrasplante inminente.","recomendaciones_nutricionales":"Evitar restricciones proteicas innecesarias, fraccionar comidas con colación nocturna, restricción de sodio a 2 g/día solo si hay ascitis, suplementación vitamínica dirigida según etiología.","ejercicio_sarcopenia":"Programa de ejercicio aeróbico y de resistencia progresiva adaptado a la condición del paciente, con objetivo de preservar masa y función muscular.","educacion":"Abstinencia completa de alcohol independientemente de la etiología, evitar automedicación con AINEs y suplementos herbales hepatotóxicos, reconocimiento de signos de alarma (ictericia nueva, confusión, sangrado, aumento de perímetro abdominal, fiebre) para consulta precoz.","referencia_trasplante":"Referencia temprana a un programa de trasplante hepático ante la primera descompensación clínica, MELD-Na ≥15, o cualquiera de los criterios específicos de descompensación grave detallados en cada complicación — no esperar al deterioro extremo, ya que el proceso de evaluación y listado requiere tiempo."},"tablas_comparativas":[{"nombre":"Child-Pugh vs. MELD vs. MELD-Na","uso":"Child-Pugh: pronóstico global y decisiones quirúrgicas no hepáticas; MELD: priorización de trasplante (mortalidad a 90 días); MELD-Na: mejora la predicción al incluir el impacto de la hiponatremia, estándar actual de asignación."},{"nombre":"West Haven (encefalopatía)","uso":"Grado 0 a IV según severidad clínica; base para decisiones de manejo ambulatorio vs. hospitalario vs. UCI."},{"nombre":"CLIF-C ACLF","uso":"Estratifica falla multiorgánica aguda sobre crónica; mejor predictor dinámico de mortalidad a 28-90 días que MELD en el contexto agudo."},{"nombre":"SAAG","uso":"Clasifica el origen de la ascitis (portal vs. no portal) con mayor precisión que la clasificación exudado/trasudado clásica."},{"nombre":"HVPG","uso":"Método de referencia para cuantificar hipertensión portal y su severidad; guía decisiones de profilaxis y evaluación de respuesta a BBNS."},{"nombre":"FIB-4 / APRI","uso":"Cribado no invasivo inicial de fibrosis avanzada en atención primaria/especializada antes de referir a estudios más específicos (elastografía)."},{"nombre":"LI-RADS / BCLC","uso":"LI-RADS caracteriza el nódulo hepático en imagen dinámica; BCLC estadifica el HCC y guía directamente la selección terapéutica."}],"perlas":["El diagnóstico de cirrosis puede establecerse por criterios clínicos, de laboratorio e imagen combinados; la biopsia hepática ya NO es obligatoria en la mayoría de los casos.","La normalidad de las transaminasas NO excluye cirrosis; en fases avanzadas (\"cirrosis quemada\") las enzimas pueden ser normales por la pérdida de masa hepatocitaria activa.","La trombocitopenia aislada e inexplicada debe hacer sospechar hipertensión portal subyacente, incluso antes que las pruebas de función hepática se alteren.","El SAAG (no la clasificación exudado/trasudado) es el método correcto para clasificar la ascitis: ≥1.1 g/dL indica hipertensión portal.","Todo paciente cirrótico hospitalizado con ascitis debe someterse a paracentesis diagnóstica al ingreso, independientemente de la presencia de síntomas.","El diagnóstico de PBE se establece con PMN ≥250/mm³ en líquido ascítico, INDEPENDIENTEMENTE del resultado del cultivo (que puede ser negativo hasta en 40% de los casos verdaderos).","La albúmina IV en PBE (1.5 g/kg día 1, 1 g/kg día 3) reduce la incidencia de síndrome hepatorrenal y la mortalidad, y debe administrarse si creatinina >1 mg/dL, BUN >30 mg/dL o bilirrubina >4 mg/dL.","Todo paciente con hemorragia digestiva variceal debe recibir antibiótico profiláctico (ceftriaxona), independientemente de si tiene o no ascitis: reduce resangrado e infecciones y mejora la supervivencia.","El TIPS precoz (24-72h) en pacientes de alto riesgo (Child-Pugh C <14 o Child B con sangrado activo) reduce la mortalidad comparado con esperar al fracaso del tratamiento estándar.","La corrección \"profiláctica\" del INR con plasma fresco antes de procedimientos de bajo riesgo (paracentesis) NO está indicada de rutina: el INR no refleja fielmente el riesgo hemorrágico real en cirrosis (rebalance hemostático).","El síndrome hepatorrenal es un diagnóstico de EXCLUSIÓN que requiere descartar choque, nefrotóxicos y daño estructural renal, además de falta de respuesta a expansión con albúmina.","La terlipresina + albúmina es el tratamiento de primera línea del HRS-AKI; la noradrenalina es una alternativa eficaz cuando la terlipresina no está disponible, requiriendo monitorización en UCI.","El amonio sérico NO es necesario para el diagnóstico clínico de encefalopatía hepática y no se correlaciona linealmente con la severidad; su normalidad debe hacer reconsiderar el diagnóstico.","La búsqueda y corrección del factor precipitante es el paso MÁS importante en el manejo de la encefalopatía hepática, más allá de la lactulosa.","La restricción proteica en la dieta del cirrótico es un mito histórico y está contraindicada de forma rutinaria: puede agravar la sarcopenia sin beneficio sobre la encefalopatía.","Platipnea y ortodeoxia (empeoramiento de la disnea/desaturación al sentarse o pararse) son característicos del síndrome hepatopulmonar, por redistribución del flujo hacia las bases pulmonares dilatadas.","La hipertensión portopulmonar y el síndrome hepatopulmonar son fisiopatológicamente OPUESTOS (vasoconstricción obstructiva vs. vasodilatación), aunque ambos ocurren en el contexto de hipertensión portal.","Los betabloqueadores no selectivos están contraindicados o deben usarse con extrema precaución en hipertensión portopulmonar moderada-severa, a diferencia del resto de indicaciones de hipertensión portal.","El TIPS está contraindicado en hipertensión portopulmonar moderada-severa por riesgo de sobrecarga aguda del ventrículo derecho.","Los cirróticos NO están protegidos de trombosis a pesar de su INR elevado; de hecho tienen igual o mayor riesgo de tromboembolismo venoso que la población general.","Carvedilol es el betabloqueador no selectivo con mayor efecto reductor del HVPG (por su actividad anti-alfa-1 adicional) y es de elección tanto en profilaxis primaria como secundaria cuando es tolerado.","La regla del 5 de Baveno VII (LSM <15 kPa + plaquetas ≥150,000) permite descartar hipertensión portal clínicamente significativa sin necesidad de HVPG o endoscopia.","El diagnóstico no invasivo de HCC (LR-5) mediante patrón de hipercaptación arterial con lavado venoso en TC/RM trifásica en hígado cirrótico NO requiere biopsia confirmatoria.","La vigilancia de HCC debe realizarse cada 6 meses (no anual) mediante ultrasonido, con o sin alfafetoproteína, en todo paciente cirrótico.","Los criterios de Milán (1 nódulo ≤5 cm o hasta 3 nódulos ≤3 cm cada uno, sin invasión vascular ni enfermedad extrahepática) siguen siendo el estándar internacional para trasplante hepático por HCC.","El ACLF se define por falla orgánica extrahepática (no solo hepática) asociada a descompensación aguda, y su mortalidad se correlaciona directamente con el número de órganos en falla.","La trayectoria del CLIF-C ACLF en los primeros 3-7 días predice mejor el pronóstico que el valor aislado al ingreso, y debe guiar la decisión de trasplante urgente.","El TIPS está contraindicado en la fase aguda de ACLF por riesgo de precipitar o agravar la encefalopatía y la inestabilidad hemodinámica.","La infección bacteriana es el precipitante identificable más frecuente de ACLF, por lo que su búsqueda activa es obligatoria ante cualquier descompensación aguda inexplicada.","El MELD-Na ≥15 o la primera descompensación clínica (no un umbral extremo) son el punto adecuado para iniciar la referencia a evaluación de trasplante hepático, dado el tiempo que requiere el proceso.","La reducción de la elastografía hepática (LSM) tras el tratamiento etiológico exitoso (p. ej. cura de VHC, abstinencia alcohólica) refleja regresión parcial de la fibrosis, confirmando que la cirrosis puede ser un proceso dinámico y parcialmente reversible en etapas tempranas."],"bibliografia":["European Association for the Study of the Liver. EASL Clinical Practice Guidelines on the management of hepatic encephalopathy. J Hepatol. 2022;77(3):807-824.","European Association for the Study of the Liver. EASL Clinical Practice Guidelines for the management of patients with decompensated cirrhosis. J Hepatol. 2018;69(2):406-460.","Biggins SW, Angeli P, Garcia-Tsao G, et al. Diagnosis, evaluation, and management of ascites, spontaneous bacterial peritonitis and hepatorenal syndrome: 2021 practice guidance by the American Association for the Study of Liver Diseases. Hepatology. 2021;74(2):1014-1048.","de Franchis R, Bosch J, Garcia-Tsao G, Reiberger T, Ripoll C; Baveno VII Faculty. Baveno VII – Renewing consensus in portal hypertension. J Hepatol. 2022;76(4):959-974.","Garcia-Tsao G, Abraldes JG, Rich NE, Wong VW. Noninvasive liver disease assessment and the prevention and management of complications of cirrhosis: 2024 AASLD Practice Guidance. Hepatology. 2024.","Moon AM, Singal AG, Tapper EB. Contemporary epidemiology of chronic liver disease and cirrhosis. Clin Gastroenterol Hepatol. 2020;18(12):2650-2666.","Angeli P, Bernardi M, Villanueva C, et al. EASL Clinical Practice Guidelines for the management of patients with decompensated cirrhosis. J Hepatol. 2018;69(2):406-460.","Vergis N, Warrillow S, Nanchal R. Diagnosis and management of acute-on-chronic liver failure. Clin Liver Dis. 2023;27(3):595-611.","Moreau R, Jalan R, Gines P, et al. Acute-on-chronic liver failure is a distinct syndrome that develops in patients with acute decompensation of cirrhosis. Gastroenterology. 2013;144(7):1426-1437.","Bajaj JS, Lauridsen M, Tapper EB, et al. Important unresolved questions in the management of hepatic encephalopathy: an ISHEN consensus. Am J Gastroenterol. 2020;115(7):989-1002.","Reiberger T. The value of liver and spleen stiffness for evaluation of portal hypertension in compensated cirrhosis. Hepatol Commun. 2022;6(5):950-964.","Kwo PY, Cohen SM, Lim JK. ACG Clinical Guideline: evaluation of abnormal liver chemistries. Am J Gastroenterol. 2017;112(1):18-35.","Fallon MB, Krowka MJ. Pulmonary complications of chronic liver disease: hepatopulmonary syndrome and portopulmonary hypertension. Hepatology. 2016;64(2):673-685.","Krowka MJ, Fallon MB, Kawut SM, et al. International Liver Transplant Society practice guidelines: diagnosis and management of hepatopulmonary syndrome and portopulmonary hypertension. Transplantation. 2016;100(7):1440-1452.","European Association for the Study of the Liver. EASL Clinical Practice Guidelines: vascular diseases of the liver. J Hepatol. 2016;64(1):179-202.","O'Leary JG, Greenberg CS, Patton HM, Caldwell SH. AGA Clinical Practice Update: coagulation in cirrhosis. Gastroenterology. 2019;157(1):34-43.","Tandon P, Montano-Loza AJ, Lai JC, Dasarathy S, Merli M. Sarcopenia and frailty in decompensated cirrhosis. J Hepatol. 2021;75(Suppl 1):S147-S162.","Guichelaar MM, Malinchoc M, Sibonga J, et al. Bone metabolism in advanced cholestatic liver disease. Hepatology 2002;36(4):895-903.","Reiberger T, Puspok A, Schoder M, et al. Austrian consensus guidelines on the management and treatment of portal hypertension. Wien Klin Wochenschr. 2017;129(Suppl 3):135-158.","Heimbach JK, Kulik LM, Finn RS, et al. AASLD guidelines for the treatment of hepatocellular carcinoma. Hepatology. 2018;67(1):358-380.","Singal AG, Llovet JM, Yarchoan M, et al. AASLD Practice Guidance on prevention, diagnosis, and treatment of hepatocellular carcinoma. Hepatology. 2023;78(6):1922-1965.","Reig M, Forner A, Rimola J, et al. BCLC strategy for prognosis prediction and treatment recommendation: the 2022 update. J Hepatol. 2022;76(3):681-693.","Kidney Disease: Improving Global Outcomes (KDIGO) Acute Kidney Injury Work Group. Angeli P, Garcia-Tsao G, Nadim MK, Parikh CR. News in pathophysiology, definition and classification of hepatorenal syndrome: a step beyond the International Club of Ascites (ICA) consensus document. J Hepatol. 2019;71(4):811-822."]};

